const BROWN_B = [
  { title: "Viking Raiders", text: ["Over twelve hundred years ago, people living on the coast of Britain dreaded the sight of a dragon-headed ship on the horizon. These were the longships of the Vikings, fierce warriors from Scandinavia.", "In AD 793, Vikings attacked the monastery on the island of Lindisfarne. They stole gold, silver and precious books, and took some of the monks as slaves. For many years after that, Viking raids terrified the people of Britain.", "However, not all Vikings came to fight. Many came looking for good farmland, because the land at home was poor and crowded. They settled in large parts of England, where they farmed, traded and made beautiful jewellery. Many English place names that end in -by, such as Whitby and Derby, come from Viking words. So do everyday English words such as sky, egg and knife."],
    q: [["Where did the Vikings come from?", ["Scandinavia", "Rome", "Egypt"], 0, "retrieval"], ["What happened at Lindisfarne in AD 793?", ["Vikings attacked the monastery.", "Vikings built a castle.", "Vikings held a market."], 0, "retrieval"], ["Why did many Vikings come to Britain to settle?", ["They wanted good farmland.", "They wanted to learn English.", "They were lost."], 0, "retrieval"], ["Which word in paragraph 1 means \"feared greatly\"?", ["dreaded", "fierce", "sight"], 0, "vocabulary"], ["How does the word \"However\" change the direction of the text?", ["It shows that the writer is giving a different side of the Vikings.", "It starts a new story.", "It shows the end of the text."], 0, "structure"]] },
  { title: "The Boy Who Cried Wolf (retold)", text: ["High in the hills above a sleepy village, a shepherd boy called Pieter watched over the sheep. The days were long and dull, and Pieter longed for some excitement.", "One afternoon, he had an idea. \"Wolf! Wolf!\" he shouted at the top of his voice. The villagers dropped their tools and raced up the hill, only to find Pieter rolling on the grass with laughter. They trudged home, grumbling.", "A week later, Pieter played the same trick, and the villagers came running again. This time, they were furious.", "Then, one misty evening, a real wolf crept out of the forest, its yellow eyes fixed on the flock. \"Wolf! Wolf!\" screamed Pieter. \"Please help me!\" But down in the village, nobody moved. \"It's just Pieter, up to his tricks again,\" they said.", "By the time Pieter's father came looking for him, half of the flock had gone."],
    q: [["Why did Pieter cry \"Wolf!\" the first time?", ["He was bored and wanted some excitement.", "He saw a wolf.", "He was lost."], 0, "inference"], ["How did the villagers feel after the second trick?", ["furious", "amused", "grateful"], 0, "retrieval"], ["Why did nobody come the third time?", ["They thought he was playing a trick again.", "They were asleep.", "They couldn't hear him."], 0, "inference"], ["Which word means \"walked slowly and heavily\"?", ["trudged", "raced", "crept"], 0, "vocabulary"], ["What is the moral of this story?", ["If you tell lies, people may not believe you when you tell the truth.", "Wolves are dangerous.", "Always look after sheep."], 0, "summarising"]] },
  { title: "The Library at Night", text: ["When the last light clicks and the doors are locked,", "And the cleaner's gone and the clock has tocked,", "The books wake up on their dusty shelves", "And whisper stories to themselves.", "The pirate tales go sailing past,", "The dinosaurs come thundering fast,", "The fairy queens in silver gowns", "Go dancing through the atlas towns.", "But when the morning sun creeps in,", "They hurry back and tuck their pages in,", "And stand in rows, so neat and prim,", "As if they'd never moved a limb."],
    q: [["When do the books wake up?", ["at night, when the library is locked", "in the morning", "at lunchtime"], 0, "retrieval"], ["What do the books do?", ["whisper stories to themselves", "read each other", "fall off the shelves"], 0, "retrieval"], ["\"The dinosaurs come thundering fast\" suggests they are…", ["loud and heavy", "quiet and small", "slow and sleepy"], 0, "language"], ["Why do the books hurry back in the morning?", ["so that nobody knows they moved", "because they are tired", "because the cleaner shouts at them"], 0, "inference"], ["Which word rhymes with \"in\"?", ["prim", "limb", "gowns"], 0, "language"]] }
];
