const BROWN_TEXTS = [
  { id: "b13-map", band: 13, title: "The Map in the Attic", type: "Story", text: ["Rain was drumming on the roof when Amir and his cousin Leila climbed into Grandpa's dusty attic. It was full of forgotten things: a rocking horse with one ear, a pile of yellowing newspapers and an old leather trunk with brass corners.", "Inside the trunk, under a heap of moth-eaten blankets, Leila found a roll of thick paper tied with a faded blue ribbon. She untied it carefully. It was a hand-drawn map of their own town, but it looked very different. Where the supermarket now stood, the map showed a small farm with a crooked windmill. And in the corner of the old park, someone had drawn a tiny red cross.", "\"Treasure!\" whispered Amir.", "The next morning, they took the map to the park. In the corner, beneath an enormous oak tree with twisted roots, they found a flat stone with the letters J.H. carved into it.", "That evening, they showed Grandpa what they had found. His eyes filled with tears. \"J.H.,\" he said softly. \"Joseph Hassan. That was my father. We buried a box of marbles there when I was your age.\"", "The next weekend, the three of them went back with a spade."],
    vocab: { attic: "a room at the top of a house, under the roof", "moth-eaten": "full of holes made by moths", crooked: "bent, not straight" },
    questions: [["What was the weather like at the start?", ["rainy", "sunny", "snowy"], 0, "retrieval"], ["Where did Leila find the map?", ["inside the trunk, under the blankets", "on the rocking horse", "in the newspapers"], 0, "retrieval"], ["How was the town on the map different?", ["There was a farm where the supermarket is now.", "There was no park.", "It had a castle."], 0, "inference"], ["Who was J.H.?", ["Grandpa's father", "Amir's teacher", "a pirate"], 0, "retrieval"], ["Why did Grandpa's eyes fill with tears?", ["It brought back happy memories of his father.", "He was angry about the map.", "He had something in his eye."], 0, "inference"]],
    grammar: Object.assign({}, BENP, { spots: ["a rocking horse with one ear", "a pile of yellowing newspapers", "an old leather trunk with brass corners", "a heap of moth-eaten blankets", "a roll of thick paper tied with a faded blue ribbon", "a small farm with a crooked windmill", "an enormous oak tree with twisted roots", "a flat stone with the letters J.H. carved into it", "a box of marbles"], practice: benpP }) },
  { id: "b13-teeth", band: 13, title: "The Digestive System", type: "Information", text: ["Every time you eat a sandwich, your body begins an amazing journey to turn it into energy. This journey is called digestion.", "First of all, in your mouth, your teeth cut and grind the food into smaller pieces. At the same time, saliva makes the food soft and starts to break it down.", "Next, when you swallow, the food travels down a long tube called the oesophagus. Muscles squeeze it along, a little like toothpaste being pushed out of a tube.", "After a few seconds, the food arrives in your stomach. Here, strong acids and churning muscles turn it into a thick, soupy liquid. This can take up to four hours.", "From the stomach, the food moves into the small intestine. Despite its name, the small intestine is about six metres long! In here, the useful nutrients pass into your blood.", "Finally, whatever your body cannot use passes into the large intestine. Water is absorbed, and the waste leaves your body when you go to the toilet.", "Altogether, the journey from mouth to toilet can take between one and three days."],
    vocab: { saliva: "spit; the liquid in your mouth", nutrients: "the useful parts of food that help your body grow and stay healthy", absorbed: "soaked up" },
    questions: [["What two jobs do teeth do?", ["cut and grind food", "make saliva and swallow", "squeeze and churn"], 0, "retrieval"], ["What is the oesophagus?", ["the tube that food travels down after you swallow", "part of your mouth", "a type of acid"], 0, "vocabulary"], ["How long can food stay in the stomach?", ["up to four hours", "a few seconds", "three days"], 0, "retrieval"], ["Why does the writer say \"Despite its name\"?", ["Because the small intestine is actually very long.", "Because it is the stomach.", "Because it is very wide."], 0, "inference"], ["How is this text organised?", ["in the order food travels through the body", "in alphabetical order", "from the least to the most important part"], 0, "structure"]],
    grammar: Object.assign({}, BFRONT, { spots: ["First of all, in your mouth,", "At the same time,", "Next, when you swallow,", "After a few seconds,", "Here,", "From the stomach,", "Despite its name,", "In here,", "Finally,", "Altogether,"], practice: bfrontP }) },
  { id: "b13-storm", band: 13, title: "Night of the Storm", type: "Story", text: ["Without warning, the lights went out. Ellie sat up in bed and listened. Outside, the wind was howling like a hungry wolf, and rain was hammering against the window.", "With her heart pounding, she felt her way along the landing to her brother's room. \"Sam?\" she whispered. \"Are you awake?\"", "\"Course I am,\" said a small voice from under the duvet. \"Who could sleep through this?\"", "Together, they crept downstairs. In the kitchen, Mum was already lighting candles. \"It's just a power cut,\" she said calmly. \"The storm has brought down a line somewhere.\"", "For the next two hours, they sat around the kitchen table in the flickering candlelight. Mum told them stories about the time she had been snowed in at her grandmother's farm. Sam made shadow animals on the wall with his hands. Ellie laughed so much that she forgot to be frightened.", "Just before midnight, with a sudden buzz, the lights came back on. Everyone blinked.", "\"Oh,\" said Sam, sounding disappointed. \"Can we turn them off again?\""],
    vocab: { landing: "the area at the top of the stairs", flickering: "shining unsteadily" },
    questions: [["What happened at the start of the story?", ["The lights went out.", "Ellie fell out of bed.", "Mum lit a fire."], 0, "retrieval"], ["\"The wind was howling like a hungry wolf\" makes the wind sound…", ["wild and scary", "soft and gentle", "happy"], 0, "language"], ["What had caused the power cut?", ["The storm had brought down a line.", "Sam had turned off the lights.", "Mum forgot to pay the bill."], 0, "retrieval"], ["How did Ellie's feelings change?", ["She went from frightened to happy.", "She went from happy to frightened.", "She stayed bored."], 0, "inference"], ["Why did Sam want to turn the lights off again?", ["He had enjoyed the time together by candlelight.", "The lights were too bright.", "He wanted to sleep."], 0, "inference"]],
    grammar: Object.assign({}, BFRONT, { spots: ["Without warning,", "Outside,", "With her heart pounding,", "Together,", "In the kitchen,", "For the next two hours,", "Just before midnight, with a sudden buzz,"], practice: bfrontP }) },
  { id: "b13-electric", band: 13, title: "Making a Circuit", type: "Instructions", text: ["Have you ever wondered how a torch works? You can find out by making a simple electrical circuit.", "You will need: a battery in a battery holder, a small bulb in a bulb holder, two wires with clips at each end and a small screwdriver.", "1. Using one wire, connect the positive end of the battery (marked +) to one side of the bulb holder.", "2. With the second wire, connect the other side of the bulb holder to the negative end of the battery (marked −).", "3. As soon as the circuit is complete, the bulb should light up!", "If the bulb does not light, check your circuit carefully. Is every clip firmly attached? Is there a gap anywhere? Electricity can only flow if the circuit is a complete loop with no breaks.", "Now try adding a switch. When the switch is open, it makes a gap, so the bulb goes out. When it is closed, the circuit is complete again.", "Safety: Never experiment with the electricity from plugs or sockets. It is very dangerous."],
    vocab: { circuit: "a complete loop that electricity can flow around", positive: "the + end of a battery", negative: "the − end of a battery" },
    questions: [["What do you connect first?", ["the positive end of the battery to the bulb holder", "the switch", "the negative end to the screwdriver"], 0, "sequencing"], ["What should happen when the circuit is complete?", ["The bulb should light up.", "The battery should get hot.", "The wire should break."], 0, "retrieval"], ["Why might the bulb not light?", ["There might be a gap in the circuit.", "The bulb is too bright.", "The battery is too new."], 0, "inference"], ["What does an open switch do?", ["It makes a gap so the bulb goes out.", "It makes the bulb brighter.", "It charges the battery."], 0, "retrieval"], ["Why is the safety note at the end important?", ["Electricity from sockets can seriously hurt you.", "Batteries are expensive.", "Bulbs break easily."], 0, "inference"]],
    grammar: Object.assign({}, BFRONT, { spots: ["Using one wire,", "With the second wire,", "As soon as the circuit is complete,", "If the bulb does not light,", "When the switch is open,", "When it is closed,"], practice: bfrontP }) },
  { id: "b13-diary", band: 13, title: "Diary of a School Trip", type: "Diary", text: ["Monday 3rd March", "Today we went on our class trip to the Natural History Museum, and it was the best day of the whole year!", "We were on the coach by eight o'clock. The journey took ages, but Mr Okoro did a quiz to pass the time. Our team won, so we each got a sticker.", "When we arrived, the first thing we saw was a huge whale skeleton hanging from the ceiling. I did a sketch of it in my notebook. It was enormous; I could have lain down inside its jaw.", "Next, we went to the dinosaur gallery. There was a moving T. rex that roared at us. Jamal said he wasn't scared, but I saw him jump!", "After lunch, we did a workshop about fossils. We were allowed to hold a real ammonite that was 150 million years old. I have never held anything so old before.", "On the way home, everybody was exhausted. Most of us fell asleep on the coach. Mr Okoro said we had been brilliant all day, and that he was proud of us.", "I can't wait to tell Mum and Dad all about it."],
    vocab: { skeleton: "the frame of bones inside a body", gallery: "a room in a museum where things are shown", ammonite: "a fossil of a sea creature with a spiral shell" },
    questions: [["What did Mr Okoro do on the coach?", ["a quiz", "a sketch", "a workshop"], 0, "retrieval"], ["What was the first thing they saw?", ["a huge whale skeleton", "a moving T. rex", "an ammonite"], 0, "retrieval"], ["Do you think Jamal was really scared? How do you know?", ["Yes, because the writer saw him jump.", "No, because he said so.", "No, because he laughed."], 0, "inference"], ["How old was the ammonite?", ["150 million years old", "150 years old", "15 years old"], 0, "retrieval"], ["How can you tell this is a diary?", ["It has a date, is in the first person and tells about the writer's day.", "It has instructions.", "It is written in verses."], 0, "structure"]],
    grammar: Object.assign({}, BSTD, { spots: ["it was the best day", "We were on the coach", "I did a sketch", "I saw him jump", "We were allowed", "I have never held", "everybody was exhausted", "we had been brilliant"], practice: bstdP }) },
  { id: "b13-bees", band: 13, title: "Why We Need Bees", type: "Information", text: ["Without bees, our dinner plates would look very different. About one in every three mouthfuls of food we eat depends on bees and other pollinating insects.", "When a bee visits a flower to collect nectar, tiny grains of yellow pollen stick to the soft hairs on its body. As the bee flies from flower to flower, some of this pollen rubs off. This is called pollination, and it allows plants to make seeds and fruit.", "Apples, strawberries, cucumbers and almonds are just a few of the foods that need bees. Even the cotton in your T-shirt comes from plants that are pollinated by insects.", "Sadly, the number of bees is falling. Pesticides, which are chemicals sprayed on crops to kill pests, can harm bees too. Bees are also losing the wild flowers they need for food.", "Luckily, everyone can help. By planting bee-friendly flowers such as lavender and sunflowers, you can provide food for bees. By leaving a patch of garden to grow wild, you can give them a place to shelter."],
    vocab: { pollinating: "carrying pollen from flower to flower", nectar: "a sweet liquid inside flowers", pesticides: "chemicals used to kill insects that harm crops" },
    questions: [["How much of our food depends on bees and other pollinators?", ["about one in every three mouthfuls", "all of it", "none of it"], 0, "retrieval"], ["How does pollen get from one flower to another?", ["It sticks to the bee and rubs off on the next flower.", "The wind blows it.", "Farmers carry it."], 0, "retrieval"], ["What are pesticides?", ["chemicals sprayed on crops to kill pests", "bee-friendly flowers", "a type of honey"], 0, "vocabulary"], ["Why is the number of bees falling?", ["Pesticides harm them and they are losing wild flowers.", "They are too big.", "People eat too much honey."], 0, "retrieval"], ["What is the writer trying to do in the last paragraph?", ["encourage readers to help bees", "describe a beehive", "explain how honey is made"], 0, "structure"]],
    grammar: Object.assign({}, BENP, { spots: ["tiny grains of yellow pollen", "the soft hairs on its body", "the cotton in your T-shirt", "the wild flowers they need for food", "a patch of garden"], practice: benpP }) },
  { id: "b13-kite", band: 13, title: "The Kite Festival", type: "Story", text: ["Every January, the people of Ahmedabad fill the sky with kites. This year, Priya was finally old enough to fly her own.", "She and her grandfather had spent weeks making it. They had bent thin strips of bamboo into a diamond and stretched bright orange tissue paper across the frame. Grandfather had painted a golden sun in the middle.", "On the morning of the festival, the rooftops were crowded with families. The air was full of music, laughter and the smell of sweet sesame snacks.", "Priya's kite rose quickly. Higher and higher it climbed, dancing among hundreds of others. But then, out of nowhere, a purple kite swooped towards hers. Its string sliced through Priya's, and her beautiful kite drifted away over the city.", "Priya's eyes stung with tears. \"We were going to win,\" she said. \"I done everything right!\"", "\"You did everything right,\" said Grandfather gently, \"and that is why it flew so well. Now, it is having an adventure of its own.\" He reached into his bag. \"Besides,\" he smiled, \"I always make two.\""],
    vocab: { bamboo: "a tall plant with strong, hollow stems", sliced: "cut cleanly" },
    questions: [["What was Priya's kite made of?", ["bamboo strips and orange tissue paper", "plastic and string", "wood and cloth"], 0, "retrieval"], ["What was painted on the kite?", ["a golden sun", "a purple star", "a dragon"], 0, "retrieval"], ["What happened to Priya's kite?", ["Another kite cut its string and it drifted away.", "It fell into a river.", "It ripped in the wind."], 0, "retrieval"], ["How does Grandfather correct Priya's grammar?", ["He changes \"I done\" to \"You did\".", "He tells her off.", "He writes it down."], 0, "language"], ["What does the ending tell us about Grandfather?", ["He is wise and kind, and planned ahead.", "He is forgetful.", "He wanted the kite for himself."], 0, "inference"]],
    grammar: Object.assign({}, BSTD, { spots: ["We were going to win", "I done everything right", "You did everything right", "They had bent", "had painted", "were crowded"], practice: bstdP }) },
  { id: "b13-letter", band: 13, title: "Letter to the Council", type: "Letter", text: ["Dear Councillor Harris,", "I am writing to ask you to keep our local park open. I heard that it might be sold to build a car park, and I think this would be a terrible mistake.", "Our park is the only green space in our part of town. Every day, children play there after school, older people walk their dogs and families have picnics on the grass. Last summer, our class did a survey and we found that over two hundred people use the park every week.", "The park is also important for wildlife. We have seen hedgehogs, foxes and woodpeckers there. If it was turned into a car park, these animals would lose their home.", "My friends and I were very upset when we heard the news. We have written a petition, and so far 340 people have signed it. We would be happy to bring it to the council office.", "Please think about all the people and animals that need our park. I hope you will make the right decision.", "Yours sincerely,", "Aisha Rahman (Year 4)"],
    vocab: { survey: "asking lots of people the same questions to find out information", petition: "a letter signed by many people asking for something to change", councillor: "a person elected to help run a town" },
    questions: [["Why is Aisha writing the letter?", ["to ask the council to keep the park open", "to complain about dogs", "to ask for a new car park"], 0, "retrieval"], ["How many people use the park every week, according to the survey?", ["over two hundred", "340", "about ten"], 0, "retrieval"], ["Which animals live in the park?", ["hedgehogs, foxes and woodpeckers", "badgers and deer", "rabbits and ducks"], 0, "retrieval"], ["Why does Aisha mention the petition?", ["to show that many people agree with her", "to show she likes writing", "to ask for money"], 0, "inference"], ["Which features show this is a formal letter?", ["It starts \"Dear Councillor\" and ends \"Yours sincerely\".", "It uses lots of slang.", "It has a list of ingredients."], 0, "structure"]],
    grammar: Object.assign({}, BSTD, { spots: ["I am writing", "our class did a survey", "we found that", "We have seen", "My friends and I were very upset", "We have written a petition"], practice: bstdP }) },
  { id: "b13-tree", band: 13, title: "The Tree in Our Playground", type: "Poem", text: ["The old horse chestnut in our yard", "Has stood for a hundred years on guard.", "In spring, its candles, pink and white,", "Light up the branches, soft and bright.", "On hot June days, beneath its shade,", "The best of all our games are played.", "In autumn, when the conkers fall,", "We gather them against the wall.", "Through winter, bare against the sky,", "It waves its fingers as we pass by.", "And though we'll leave, as children do,", "It stays to watch the children new."],
    vocab: { conkers: "the shiny brown seeds of a horse chestnut tree", "on guard": "watching over and protecting" },
    questions: [["How long has the tree stood in the yard?", ["a hundred years", "ten years", "a thousand years"], 0, "retrieval"], ["What are the \"candles\" in spring?", ["the tree's flowers", "real candles", "the conkers"], 0, "inference"], ["What do the children do in autumn?", ["gather conkers", "sit in the shade", "climb the tree"], 0, "retrieval"], ["\"It waves its fingers\" describes…", ["the bare branches moving", "the children waving", "the leaves falling"], 0, "language"], ["What does the last verse mean?", ["The tree will still be there for future children after we leave.", "The tree will be cut down.", "The children will never leave."], 0, "inference"]],
    grammar: Object.assign({}, BFRONT, { spots: ["In spring,", "On hot June days, beneath its shade,", "In autumn, when the conkers fall,", "Through winter, bare against the sky,"], practice: bfrontP }) },
  { id: "b13-market", band: 13, title: "The Spice Market", type: "Poem", text: ["Under a roof of coloured cloth,", "Where lanterns sway and pigeons coo,", "Are mountains of red chilli powder", "And sacks of cloves and cumin too.", "A wrinkled man with a silver beard", "Weighs saffron on a brass-pan scale,", "While a girl in a scarf of sunset gold", "Sells cinnamon sticks from a rusty pail.", "The air is thick with pepper sneezes,", "Cardamom, ginger, nutmeg, mace;", "If you ever want to travel the world,", "Just close your eyes in this crowded place."],
    vocab: { saffron: "an expensive orange-yellow spice", pail: "a bucket" },
    questions: [["What is the roof of the market made of?", ["coloured cloth", "glass", "wood"], 0, "retrieval"], ["Who weighs saffron?", ["a wrinkled man with a silver beard", "a girl in a scarf", "a pigeon"], 0, "retrieval"], ["Why might the air make you sneeze?", ["It is full of pepper and spices.", "It is cold.", "There are too many pigeons."], 0, "inference"], ["What does \"mountains of red chilli powder\" tell us?", ["There are very large piles of it.", "The market is in the mountains.", "The chilli is very hot."], 0, "language"], ["What does the poet mean in the last two lines?", ["The smells make you feel as if you have travelled the world.", "You should travel by plane.", "The market is very dark."], 0, "inference"]],
    grammar: Object.assign({}, BENP, { spots: ["a roof of coloured cloth", "mountains of red chilli powder", "sacks of cloves and cumin", "A wrinkled man with a silver beard", "a girl in a scarf of sunset gold", "a rusty pail"], practice: benpP }) }
];
