const GREY_B = [
  { title: "The Great Fire of London", text: ["In the early hours of Sunday 2nd September 1666, a fire broke out in a bakery on Pudding Lane. It belonged to Thomas Farriner, the King's baker. At first, nobody was very worried. The Lord Mayor was woken up, but he said the fire was so small that it could easily be put out.", "He was wrong. London's houses were made of wood and were packed closely together. The summer had been long and dry, and a strong wind blew the flames from street to street. The fire burned for four days.", "People tried to escape by boat along the River Thames, carrying whatever they could. Samuel Pepys, a man who kept a famous diary, even buried his cheese and wine in his garden to keep them safe!", "By the time the fire was put out, it had destroyed more than 13,000 houses and 87 churches, including St Paul's Cathedral. Afterwards, London was rebuilt using brick and stone instead of wood."],
    q: [["Where did the fire start?", ["in a bakery on Pudding Lane", "in St Paul's Cathedral", "on a boat"], 0, "retrieval"], ["Why did the Lord Mayor not worry at first?", ["He thought the fire was small.", "He was asleep.", "He was on holiday."], 0, "retrieval"], ["Give one reason the fire spread so quickly.", ["The houses were made of wood and packed closely together.", "There was too much rain.", "People started new fires."], 0, "inference"], ["What did Samuel Pepys bury?", ["his cheese and wine", "his diary", "his money"], 0, "retrieval"], ["How did the fire change London?", ["It was rebuilt using brick and stone.", "It was never rebuilt.", "It moved to a new place."], 0, "summarising"]] },
  { title: "The Swap", text: ["Isla and her twin brother, Finn, looked so alike that even their grandmother sometimes muddled them up. One morning, they decided to swap places for the day.", "Isla put on Finn's football shirt, and Finn borrowed Isla's glasses. At school, they sat in each other's seats. Nobody noticed a thing.", "The problem began at lunch. Finn was supposed to be in the girls' football team photograph, and Isla had to go to Finn's clarinet lesson. Isla had never played the clarinet in her life.", "\"Let's begin with the piece you practised last week,\" said the music teacher, smiling.", "Isla lifted the clarinet. She blew. The noise that came out sounded like a goose with a cold. The teacher's smile froze.", "Meanwhile, on the field, Finn tripped over the ball and landed face-first in the mud, just as the camera flashed.", "That evening, they told their parents everything. \"Well,\" laughed Dad, \"I hope you've learned your lesson.\" \"We have,\" groaned the twins. \"Being someone else is much harder than it looks.\""],
    q: [["Why could the twins swap places?", ["They looked very alike.", "Their teacher let them.", "They wore masks."], 0, "retrieval"], ["What did Isla have to do?", ["go to Finn's clarinet lesson", "be in a football photo", "play the piano"], 0, "retrieval"], ["\"The teacher's smile froze\" shows the teacher was…", ["shocked", "delighted", "cold"], 0, "language"], ["What happened to Finn?", ["He fell in the mud as the photo was taken.", "He scored a goal.", "He was sent home."], 0, "retrieval"], ["What did the twins learn?", ["Being someone else is harder than it looks.", "Clarinets are easy.", "Football is fun."], 0, "summarising"]] },
  { title: "The Puddle", text: ["After the rain, in the playground's dip,", "There's a puddle as wide as a pirate ship.", "The teachers' warnings fill the air:", "\"Keep your feet out! Don't you dare!\"", "But the puddle winks with a silver eye,", "Holding a piece of the upside-down sky.", "The clouds float past in its rippling glass,", "And pigeons stop to drink as they pass.", "Then the bell goes, and the children race;", "One small boot lands — splash! — in place.", "The puddle grins from ear to ear:", "\"I knew you couldn't resist me, dear.\""],
    q: [["How big is the puddle?", ["as wide as a pirate ship", "as small as a coin", "as deep as a well"], 0, "language"], ["What do the teachers say?", ["Keep your feet out!", "Jump in!", "Fetch a towel!"], 0, "retrieval"], ["What can be seen in the puddle?", ["the sky and clouds", "fish", "a pirate ship"], 0, "retrieval"], ["How does the poet make the puddle seem alive?", ["It winks and grins and speaks.", "It has a name.", "It is very big."], 0, "language"], ["What happens at the end?", ["A child jumps in the puddle.", "The puddle dries up.", "The teachers jump in."], 0, "retrieval"]] }
];
const GPOS = { focus: "Plural and possessive -s", explain: "An -s at the end of a word can mean more than one (the dogs) or something belonging to someone (the dog's bone). For one owner, put the apostrophe before the s: the girl's bag. For a plural ending in s, put it after: the girls' bags. For irregular plurals, add 's: the children's toys." };
const GCOH = { focus: "Pronouns and nouns for cohesion", explain: "Writers swap between nouns and pronouns (he, she, it, they, this) so they don't repeat the same word, but they make sure it is always clear who or what they mean. This helps the writing flow." };
const gposP = [["Which means \"the toys belonging to the children\"?", ["the children's toys", "the childrens' toys", "the childrens toys"], 0], ["Which means \"the bags belonging to the girls\"?", ["the girls' bags", "the girl's bags", "the girls bags"], 0], ["Which means \"more than one dog\"?", ["dogs", "dog's", "dogs'"], 0]];
const gcohP = [["\"Sam lost his hat. ___ was red.\" Which word fits?", ["It", "He", "They"], 0], ["Why do writers use pronouns?", ["to avoid repeating the same noun", "to make sentences longer", "to show who is speaking"], 0], ["In \"The bees left the hive because it was full\", what does \"it\" refer to?", ["the hive", "the bees", "the honey"], 0]];
const GREY_TEXTS = [
  { id: "gr14-sports", band: 14, title: "Sports Day Disaster", type: "Story", text: ["The parents' cheers grew louder as the Year 4 relay team lined up. Ravi held the baton tightly. His team's chance of winning depended on him.", "The race began. Ravi's teammates ran brilliantly, and by the third leg, the Red team was in the lead. Ravi waited, his heart thumping. Lucy raced towards him and passed the baton perfectly.", "Ravi ran faster than he had ever run before. But halfway down the track, his trainer's lace came undone. He stumbled, wobbled and fell flat on the grass.", "The other teams' runners rushed past him. Ravi lay there, wanting the ground to swallow him up. Then he heard a sound. It was his classmates' voices, chanting his name.", "Ravi got up. He picked up the baton and ran to the finish line. He came last, but the whole crowd was on its feet, clapping.", "Afterwards, the head teacher gave out the medals. The winners' medals were gold. But then she called Ravi's name. \"This one,\" she said, \"is for the most determined runner of the day.\""],
    vocab: { baton: "a short stick passed between runners in a relay", leg: "one part of a relay race", determined: "not giving up" },
    questions: [["What was Ravi holding?", ["the baton", "a medal", "a trophy"], 0, "retrieval"], ["Why did Ravi fall?", ["His trainer's lace came undone.", "Someone pushed him.", "He was tired."], 0, "retrieval"], ["\"Wanting the ground to swallow him up\" shows he felt…", ["embarrassed", "proud", "angry"], 0, "language"], ["What made Ravi get up?", ["hearing his classmates chant his name", "the teacher shouting", "the bell ringing"], 0, "inference"], ["Why did Ravi get a special medal?", ["He didn't give up and finished the race.", "He won the race.", "He was the fastest."], 0, "inference"]],
    grammar: Object.assign({}, GPOS, { spots: ["The parents' cheers", "His team's chance", "Ravi's teammates", "his trainer's lace", "The other teams' runners", "his classmates' voices", "The winners' medals", "Ravi's name"], practice: gposP }) },
  { id: "gr14-teeth", band: 14, title: "Animal Teeth", type: "Information", text: ["You can tell a lot about an animal by looking at its teeth. Teeth show what an animal eats and how it eats.", "Herbivores, such as cows and rabbits, only eat plants. Their teeth are mostly wide and flat, which is perfect for grinding up grass and leaves. A rabbit's front teeth never stop growing, so it must keep chewing to wear them down.", "Carnivores, such as lions and wolves, eat meat. They have long, pointed teeth called canines, which they use for gripping and tearing. A lion's canines can be up to ten centimetres long!", "Omnivores eat both plants and meat. Humans are omnivores. Our mouths contain several different kinds of teeth. The incisors at the front cut food. The canines tear it, and the molars at the back grind it.", "Some animals have no teeth at all. Birds use their beaks instead. Many birds swallow small stones, which help to grind the food up inside their stomachs.", "So next time you visit the zoo, take a look at the animals' teeth. They will tell you what's on the menu!"],
    vocab: { herbivores: "animals that only eat plants", carnivores: "animals that eat meat", omnivores: "animals that eat both plants and meat" },
    questions: [["What do herbivores eat?", ["only plants", "only meat", "plants and meat"], 0, "retrieval"], ["Why must a rabbit keep chewing?", ["Its front teeth never stop growing.", "It is always hungry.", "It has no molars."], 0, "retrieval"], ["What are canines used for?", ["gripping and tearing", "grinding", "cutting grass"], 0, "retrieval"], ["What is an omnivore?", ["an animal that eats both plants and meat", "an animal with no teeth", "a bird"], 0, "vocabulary"], ["Why do some birds swallow stones?", ["to help grind food in their stomachs", "because they are hungry", "to make themselves heavier"], 0, "retrieval"]],
    grammar: Object.assign({}, GCOH, { spots: ["its teeth", "Their teeth", "so it must keep chewing to wear them down", "which they use for gripping and tearing", "Our mouths", "They will tell you"], practice: gcohP }) },
  { id: "gr14-tudors", band: 14, title: "Henry VIII and His Six Wives", type: "Information", text: ["Henry VIII became King of England in 1509, when he was only seventeen. He was tall, clever and good at sport. He loved music, dancing and hunting. However, he is most famous for marrying six times.", "Henry's first wife was Catherine of Aragon. They were married for over twenty years, and they had a daughter, Mary. However, Henry desperately wanted a son to become king after him. When the Pope refused to end his marriage, Henry broke away from the Catholic Church and made himself head of the Church of England.", "His second wife, Anne Boleyn, gave birth to a daughter, Elizabeth, who would one day become one of England's greatest queens. His third wife, Jane Seymour, finally gave him a son, Edward. Sadly, she died soon afterwards.", "Henry's last three wives were Anne of Cleves, Catherine Howard and Catherine Parr. Catherine Parr outlived him.", "A rhyme helps children remember what happened to the wives: divorced, beheaded, died; divorced, beheaded, survived."],
    vocab: { desperately: "wanting something very, very much", outlived: "lived longer than someone else" },
    questions: [["How old was Henry when he became king?", ["seventeen", "twenty", "nine"], 0, "retrieval"], ["Why did Henry want to end his first marriage?", ["He wanted a son to become king after him.", "He didn't like music.", "He wanted to move to Spain."], 0, "inference"], ["What did Henry do when the Pope refused?", ["made himself head of the Church of England", "went to war with Spain", "gave up the throne"], 0, "retrieval"], ["Which wife gave Henry a son?", ["Jane Seymour", "Anne Boleyn", "Catherine Parr"], 0, "retrieval"], ["Why is the rhyme useful?", ["It helps you remember what happened to each wife.", "It was written by Henry.", "It is a song to dance to."], 0, "inference"]],
    grammar: Object.assign({}, GCOH, { spots: ["He was tall, clever and good at sport", "They were married for over twenty years", "his marriage", "who would one day become one of England's greatest queens", "she died soon afterwards", "Catherine Parr outlived him"], practice: gcohP }) },
  { id: "gr14-shop", band: 14, title: "The Toy Shop Mystery", type: "Story", text: ["Every night at closing time, Mr Fischer locked the doors of his toy shop. And every morning, something had changed.", "On Monday, the teddy bears' picnic had moved from the window to the counter. On Tuesday, the soldiers' drums were found inside the dolls' house. On Wednesday, the puppets' strings were tangled together in a knot.", "Mr Fischer's granddaughter, Greta, decided to solve the mystery. That night, she hid behind the rocking horses with a torch and a notebook.", "At midnight, she heard a scratching sound. Something small was moving along the shelves. Greta held her breath and switched on her torch.", "There, sitting in the middle of the toy kitchen, was a little brown mouse. It was nibbling a biscuit from a doll's tea set. Around it, the toys' tiny cups and plates were scattered everywhere.", "\"So you're the culprit!\" laughed Greta.", "The next day, she made the mouse a cosy home in a shoebox at the back of the shop. Since then, the toys have stayed exactly where they belong, and the mouse has become the shop's most famous resident."],
    vocab: { culprit: "the person or animal that did something wrong", resident: "someone who lives in a place" },
    questions: [["What happened to the puppets on Wednesday?", ["Their strings were tangled.", "They moved to the window.", "They disappeared."], 0, "retrieval"], ["Where did Greta hide?", ["behind the rocking horses", "under the counter", "in the dolls' house"], 0, "retrieval"], ["What had been moving the toys?", ["a little brown mouse", "Mr Fischer", "the toys themselves"], 0, "retrieval"], ["What is a \"culprit\"?", ["someone who did something wrong", "a kind of mouse", "a toy"], 0, "vocabulary"], ["How did Greta solve the problem kindly?", ["She gave the mouse a home in a shoebox.", "She set a trap.", "She got a cat."], 0, "inference"]],
    grammar: Object.assign({}, GPOS, { spots: ["the teddy bears' picnic", "the soldiers' drums", "the dolls' house", "the puppets' strings", "Mr Fischer's granddaughter", "a doll's tea set", "the toys' tiny cups and plates", "the shop's most famous resident"], practice: gposP }) },
  { id: "gr14-water", band: 14, title: "The Water Cycle", type: "Information", text: ["The water you drink today might once have been drunk by a dinosaur! This is because the Earth's water is used again and again in a never-ending journey called the water cycle.", "It begins when the sun heats water in oceans, rivers and lakes. The water turns into an invisible gas called water vapour, and it rises into the air. This is called evaporation.", "As the vapour rises, it cools down. It turns back into tiny droplets of water, which join together to form clouds. This process is called condensation.", "When the droplets become too heavy, they fall back to the ground as rain, snow, sleet or hail. Scientists call this precipitation.", "Some of this water soaks into the ground, where plants' roots can reach it. The rest runs into streams and rivers, which carry it back to the sea. There, the sun heats it again, and the whole cycle starts once more.", "So remember: every glass of water has been on an amazing journey, and it has probably been round the world many times!"],
    vocab: { evaporation: "when a liquid turns into a gas", condensation: "when a gas cools and turns back into a liquid", precipitation: "water falling from clouds as rain, snow, sleet or hail" },
    questions: [["Why might your water once have been drunk by a dinosaur?", ["The Earth's water is used again and again.", "Dinosaurs lived in rivers.", "Water lasts forever in bottles."], 0, "inference"], ["What is evaporation?", ["when water turns into a gas", "when rain falls", "when clouds form"], 0, "vocabulary"], ["What forms clouds?", ["tiny droplets of water joining together", "smoke", "dust"], 0, "retrieval"], ["Name one form of precipitation.", ["hail", "vapour", "steam"], 0, "retrieval"], ["How is the text organised?", ["It follows the stages of the cycle in order.", "It is in alphabetical order.", "It compares two rivers."], 0, "structure"]],
    grammar: Object.assign({}, GCOH, { spots: ["It begins when the sun heats water", "it rises into the air", "This is called evaporation", "it cools down", "This process is called condensation", "they fall back to the ground", "Scientists call this precipitation", "which carry it back to the sea"], practice: gcohP }) },
  { id: "gr14-lunch", band: 14, title: "The School Council's Plan", type: "Report", text: ["Last term, the school council decided to find out what pupils thought about lunchtimes. The councillors' first job was to write a survey.", "They asked every class three questions: What do you like about lunchtime? What would you change? What new activities would you like?", "More than three hundred pupils' answers came back. The councillors spent two weeks reading them. They found that most children enjoyed the food, but many said the playground was too crowded. Lots of the younger pupils' answers said they felt worried by the big children's football games.", "The council made a plan. They suggested splitting the playground into zones: a football zone, a quiet zone and a games zone. They also asked if the library could open at lunchtime for pupils who wanted somewhere calm.", "The head teacher agreed to try the plan for half a term. It has been a success. The midday supervisors' reports show that there have been fewer arguments, and the library's lunchtime club now has forty members.", "The council's next project is to raise money for new playground equipment."],
    vocab: { councillors: "members of a council", survey: "a set of questions asked to lots of people", supervisors: "adults who look after children" },
    questions: [["What did the council want to find out?", ["what pupils thought about lunchtimes", "which teacher was best", "how to raise money"], 0, "retrieval"], ["What problem did many pupils mention?", ["The playground was too crowded.", "The food was cold.", "Lunch was too short."], 0, "retrieval"], ["Why might younger pupils feel worried?", ["The big children's football games were rough and crowded.", "They didn't like the food.", "They were lost."], 0, "inference"], ["What evidence shows the plan worked?", ["fewer arguments, and forty members in the library club", "the head teacher was happy", "it was sunny"], 0, "retrieval"], ["What is the purpose of this report?", ["to explain what the council did and what happened", "to tell a funny story", "to give a recipe"], 0, "structure"]],
    grammar: Object.assign({}, GPOS, { spots: ["The councillors' first job", "three hundred pupils' answers", "the younger pupils' answers", "the big children's football games", "The midday supervisors' reports", "the library's lunchtime club", "The council's next project"], practice: gposP }) },
  { id: "gr14-wolf", band: 14, title: "Return of the Wolves", type: "Information", text: ["In 1995, something remarkable happened in Yellowstone National Park in the USA. After seventy years away, wolves were brought back.", "Before then, there had been no wolves in the park, and the number of elk, a large kind of deer, had grown and grown. They ate so many young trees and plants along the riverbanks that the trees could not grow back.", "When the wolves returned, they began to hunt the elk. The elk started to avoid the open river valleys, where they were easy to spot. Because of this, the trees there were able to grow again.", "The trees brought birds back to the valleys. Beavers returned too, and they used the trees to build dams. Their dams created ponds, which became homes for fish, frogs and otters.", "The trees' roots also held the riverbanks together, so the soil stopped washing away. In a way, the wolves even changed the shape of the rivers!", "Scientists call this a trophic cascade: a change at the top of a food chain that ripples all the way down. It shows how every living thing is connected."],
    vocab: { remarkable: "unusual and surprising", elk: "a large kind of deer", cascade: "a series of things that happen one after another, like a waterfall" },
    questions: [["When were wolves brought back to Yellowstone?", ["1995", "1925", "2015"], 0, "retrieval"], ["Why couldn't the trees grow before the wolves came back?", ["The elk ate too many young trees.", "There was no rain.", "Beavers cut them down."], 0, "retrieval"], ["Why did the elk avoid the open valleys?", ["They were easy for wolves to spot there.", "There was no food.", "It was too cold."], 0, "inference"], ["How did beavers help other animals?", ["Their dams created ponds for fish, frogs and otters.", "They hunted the elk.", "They planted trees."], 0, "retrieval"], ["What is the main message of the text?", ["Every living thing is connected.", "Wolves are dangerous.", "Beavers build dams."], 0, "summarising"]],
    grammar: Object.assign({}, GCOH, { spots: ["They ate so many young trees", "they began to hunt the elk", "where they were easy to spot", "Because of this", "they used the trees to build dams", "Their dams created ponds", "It shows how every living thing is connected"], practice: gcohP }) },
  { id: "gr14-bakery", band: 14, title: "Grandma Rosa's Bakery", type: "Story", text: ["Grandma Rosa's bakery had stood on the corner of Mill Street for fifty years. Every morning at five o'clock, its windows glowed with warm yellow light, and the smell of fresh bread drifted down the street.", "One day, a sign appeared on the empty shop across the road: Coming Soon – SuperBake. Grandma Rosa read it and sighed. SuperBake's shops were everywhere, and their cakes were cheap.", "When the new shop opened, the street was busy with customers. Grandma Rosa's shelves stayed full, and her loaves went stale.", "Her grandson Marco had an idea. \"People don't know your story, Grandma,\" he said. Together, they put photographs in the window: Rosa as a young woman, her parents' first oven, and a newspaper picture of the queue on the bakery's opening day.", "Marco also started a Saturday class where children could learn to make bread. The children's loaves were lumpy and lopsided, but the parents' smiles were enormous.", "Slowly, the customers came back. By the end of the year, the queue outside Grandma Rosa's was longer than ever. Across the road, the SuperBake sign quietly came down."],
    vocab: { stale: "old and dry, no longer fresh", lopsided: "with one side lower than the other" },
    questions: [["How long had the bakery been there?", ["fifty years", "five years", "a hundred years"], 0, "retrieval"], ["Why was Grandma Rosa worried about SuperBake?", ["Its shops were everywhere and its cakes were cheap.", "It was very noisy.", "It sold toys."], 0, "inference"], ["What did Marco put in the window?", ["photographs telling the bakery's story", "a sale sign", "new cakes"], 0, "retrieval"], ["What does \"stale\" mean?", ["old and dry", "fresh and warm", "burnt"], 0, "vocabulary"], ["Why do you think the customers came back?", ["They liked the bakery's story and the community feeling.", "SuperBake closed first.", "Rosa lowered her prices."], 0, "inference"]],
    grammar: Object.assign({}, GPOS, { spots: ["Grandma Rosa's bakery", "SuperBake's shops", "Grandma Rosa's shelves", "her parents' first oven", "the bakery's opening day", "The children's loaves", "the parents' smiles"], practice: gposP }) },
  { id: "gr14-friends", band: 14, title: "Two Friends", type: "Poem", text: ["My friend and I are different, it's true:", "She likes red, and I like blue.", "She's loud and fast, I'm slow and shy,", "She likes to run, I like to fly", "On paper planes and daydreams far;", "She's the sun and I'm a star.", "But when it rains, we share a coat,", "When she is sad, I write a note,", "When I am stuck, she lends a hand,", "When she's confused, I understand.", "We're not the same, and that's all right:", "Together, we're both day and night."],
    vocab: { daydreams: "pleasant thoughts you have while awake" },
    questions: [["What colour does the poet like?", ["blue", "red", "yellow"], 0, "retrieval"], ["How is the poet different from her friend?", ["The poet is slow and shy; the friend is loud and fast.", "They both like running.", "The poet is older."], 0, "retrieval"], ["What do they share when it rains?", ["a coat", "an umbrella", "a note"], 0, "retrieval"], ["\"She's the sun and I'm a star\" suggests…", ["they shine in different ways", "they live in space", "they don't like each other"], 0, "language"], ["What is the main message of the poem?", ["Friends can be different and still help each other.", "Friends should be the same.", "It is better to be loud."], 0, "summarising"]],
    grammar: Object.assign({}, GCOH, { spots: ["My friend and I", "She likes red", "She's loud and fast", "we share a coat", "When she is sad, I write a note", "she lends a hand", "Together, we're both day and night"], practice: gcohP }) },
  { id: "gr14-bees", band: 14, title: "The Beekeeper's Song", type: "Poem", text: ["In the beekeeper's garden, by the old stone wall,", "The hives stand in a row, like houses in a street,", "And the bees' busy humming is the sweetest sound of all,", "As they hurry from the clover with their pollen-dusted feet.", "The flowers' faces open to the warm July sun;", "The bees dive in for nectar, then they're off and away.", "The worker bees' long journeys are never really done:", "They fly a thousand miles for one small honey tray.", "So when you spread your honey on a slice of toast,", "Think of all the bees' hard work, and thank them most."],
    vocab: { hives: "the homes where bees live", clover: "a small plant with three round leaves and sweet flowers" },
    questions: [["What do the hives look like?", ["houses in a street", "boxes of toys", "stones"], 0, "language"], ["Where do the bees get pollen from?", ["the clover", "the wall", "the toast"], 0, "retrieval"], ["What is \"the sweetest sound of all\"?", ["the bees' humming", "the birds singing", "the wind"], 0, "retrieval"], ["What does the poet want us to think about when we eat honey?", ["how hard the bees worked", "the price of honey", "the beekeeper's garden"], 0, "inference"], ["What does \"never really done\" tell us about the worker bees?", ["They are always busy working.", "They are lazy.", "They are very old."], 0, "inference"]],
    grammar: Object.assign({}, GPOS, { spots: ["the beekeeper's garden", "the bees' busy humming", "The flowers' faces", "The worker bees' long journeys", "the bees' hard work"], practice: gposP }) }
];
