ASSESS[7] = [
  { id: "as7-1", title: "The Night Owl", type: "Story", text: ["Every night, when the moon came up, Olly the owl woke up and stretched his wings.", "\"Time for breakfast!\" he hooted, as the other birds went to sleep.", "Olly flew silently over the dark wood. His big eyes helped him to see in the dark.", "Suddenly, he heard a tiny squeak in the grass. He swooped down, but it was only his friend, Mo the mouse.", "\"Don't eat me!\" squeaked Mo. Olly laughed. \"I'm looking for beetles tonight, not friends!\""],
    questions: [["When does Olly wake up?", ["when the moon comes up", "in the morning", "at lunchtime"], 0, "retrieval"], ["What helps Olly see in the dark?", ["his big eyes", "a torch", "the stars"], 0, "retrieval"], ["Why is Olly's \"breakfast\" at night?", ["Owls are awake at night.", "He forgot to eat.", "He is very hungry."], 0, "inference"], ["What does \"swooped\" mean?", ["flew down quickly", "walked slowly", "jumped up"], 0, "vocabulary"], ["Why did Mo squeak \"Don't eat me!\"?", ["He was frightened of the owl.", "He was hungry.", "He wanted to play."], 0, "inference"], ["What is Olly looking for tonight?", ["beetles", "mice", "worms"], 0, "retrieval"]],
    grammar: [["Which sentence ends with an exclamation mark?", ["\"Don't eat me!\" squeaked Mo.", "Olly flew over the wood.", "Did Olly see Mo?"], 0], ["Add -ed: \"Olly ___ (hoot) loudly.\"", ["hooted", "hootted", "hooting"], 0]] },
  { id: "as7-2", title: "Penguins", type: "Information", text: ["Penguins are birds, but they cannot fly. Instead, they are excellent swimmers.", "Their wings work like flippers to push them through the water. They can swim faster than you can run!", "Most penguins live in very cold places near the South Pole. Thick feathers and a layer of fat keep them warm.", "Penguins eat fish, squid and tiny sea creatures called krill.", "On the ice, penguins waddle or slide on their tummies. Have you ever seen a penguin slide?"],
    questions: [["What can penguins not do?", ["fly", "swim", "walk"], 0, "retrieval"], ["What do penguins' wings work like?", ["flippers", "arms", "sails"], 0, "retrieval"], ["What keeps penguins warm?", ["thick feathers and a layer of fat", "coats", "the sun"], 0, "retrieval"], ["What are krill?", ["tiny sea creatures", "a kind of bird", "ice"], 0, "vocabulary"], ["What does \"waddle\" mean?", ["walk from side to side", "fly high", "swim fast"], 0, "vocabulary"], ["Why does the writer ask a question at the end?", ["to make the reader think and join in", "because they don't know", "to start a story"], 0, "structure"]],
    grammar: [["Which sentence is a question?", ["Have you ever seen a penguin slide?", "Penguins are birds.", "They eat fish."], 0], ["Which word has the suffix -er?", ["faster", "fast", "fasting"], 0]] },
  { id: "as7-3", title: "Grandma's Garden", type: "Story", text: ["On Saturday, Zara helped Grandma in the garden.", "First, they pulled up the weeds. Then they watered the beans and picked the ripest tomatoes.", "Zara found a fat, wriggly worm. \"Yuck!\" she shouted.", "\"Worms are our friends,\" smiled Grandma. \"They make the soil healthy, so our plants can grow.\"", "Zara looked at the worm again. She gently put it back in the soil. \"Thank you, worm,\" she whispered."],
    questions: [["What did they do first?", ["pulled up the weeds", "watered the beans", "picked tomatoes"], 0, "sequencing"], ["What did Zara find?", ["a worm", "a snail", "a frog"], 0, "retrieval"], ["How did Zara feel when she first saw the worm?", ["disgusted", "excited", "sad"], 0, "inference"], ["Why are worms good for the garden?", ["They make the soil healthy.", "They eat weeds.", "They water plants."], 0, "retrieval"], ["How did Zara's feelings about the worm change?", ["from disgusted to thankful", "from happy to angry", "they did not change"], 0, "inference"], ["What does \"ripest\" mean?", ["most ready to eat", "smallest", "greenest"], 0, "vocabulary"]],
    grammar: [["Which word ends with -est?", ["ripest", "ripe", "riper"], 0], ["Which sentence ends with an exclamation mark?", ["\"Yuck!\" she shouted.", "She found a worm.", "Are worms friends?"], 0]] },
  { id: "as7-4", title: "Making a Sandwich", type: "Instructions", text: ["Are you hungry? Here is how to make a tasty cheese sandwich.", "You need: two slices of bread, butter, cheese and a knife.", "1. Spread butter on one side of each slice of bread.", "2. Put the cheese on one slice.", "3. Put the other slice on top, with the butter on the inside.", "4. Cut the sandwich in half.", "Now it's ready to eat. Enjoy!"],
    questions: [["What kind of sandwich is this?", ["cheese", "jam", "egg"], 0, "retrieval"], ["How many slices of bread do you need?", ["two", "one", "four"], 0, "retrieval"], ["What do you do before putting the cheese on?", ["spread the butter", "cut the sandwich", "eat it"], 0, "sequencing"], ["What is the last step?", ["Cut the sandwich in half.", "Put the cheese on.", "Spread the butter."], 0, "sequencing"], ["What kind of text is this?", ["instructions", "a story", "a poem"], 0, "structure"], ["What does \"spread\" mean here?", ["cover thinly", "throw away", "fold up"], 0, "vocabulary"]],
    grammar: [["Which sentence is a question?", ["Are you hungry?", "Cut the sandwich in half.", "Enjoy!"], 0], ["Which word has the prefix un-?", ["unbuttered", "butter", "buttering"], 0]] },
  { id: "as7-5", title: "The Big Race", type: "Story", text: ["It was sports day, and Tom was in the running race.", "Bang! went the whistle. Tom ran as fast as he could. He was in front!", "But then his shoelace came undone. Tom tripped and fell.", "The other children ran past him. Tom felt like crying.", "Then he got up, tied his lace and finished the race. He came last, but everyone cheered the loudest for him.", "\"You never gave up,\" said Miss Lee. \"That makes you a winner.\""],
    questions: [["What day was it?", ["sports day", "a birthday", "a holiday"], 0, "retrieval"], ["Why did Tom fall?", ["His shoelace came undone.", "Someone pushed him.", "He was tired."], 0, "retrieval"], ["How did Tom feel after he fell?", ["like crying", "happy", "angry"], 0, "inference"], ["What did Tom do next?", ["tied his lace and finished", "went home", "sat down"], 0, "sequencing"], ["Why did everyone cheer loudest for Tom?", ["He did not give up.", "He won.", "He was fastest."], 0, "inference"], ["What does Miss Lee mean?", ["Trying your best matters most.", "Tom won the race.", "Tom should run faster."], 0, "summarising"]],
    grammar: [["Which word has the prefix un-?", ["undone", "done", "doing"], 0], ["Which word ends with -est?", ["loudest", "loud", "louder"], 0]] },
  { id: "as7-6", title: "Rain", type: "Poem", text: ["Pitter, patter, on the pane,", "Here comes the dripping, dropping rain!", "It fills the puddles, wets the street,", "It splashes on my wellie feet.", "The flowers drink, the ducks all quack,", "Will the sunshine ever come back?"],
    questions: [["What sound does the rain make on the pane?", ["pitter, patter", "bang, bang", "woof, woof"], 0, "language"], ["What does the rain fill?", ["puddles", "cups", "baths"], 0, "retrieval"], ["What are \"wellie feet\"?", ["feet in wellington boots", "wet socks", "bare feet"], 0, "vocabulary"], ["Why might the flowers be happy?", ["They need water to drink.", "They like the cold.", "They want to sleep."], 0, "inference"], ["Which word rhymes with \"rain\"?", ["pane", "street", "quack"], 0, "language"], ["What does the poet wonder at the end?", ["if the sun will come back", "where the ducks are", "why it is cold"], 0, "retrieval"]],
    grammar: [["Which line is a question?", ["Will the sunshine ever come back?", "It fills the puddles.", "Here comes the rain!"], 0], ["Add -ing: drip →", ["dripping", "driping", "dripeing"], 0]] }
];
ASSESS[8] = [
  { id: "as8-1", title: "The Lighthouse Cat", type: "Story", text: ["On a rocky island far out at sea stood a tall white lighthouse. Inside lived a keeper called Mr Pike and his clever ginger cat, Marmalade.", "Every night, Mr Pike climbed the winding stairs to light the great lamp, so that ships would not crash into the rocks.", "One stormy evening, Mr Pike fell asleep in his chair. The lamp was still dark, and a fishing boat was heading straight for the rocks!", "Marmalade jumped onto Mr Pike's lap and miaowed loudly in his ear. Mr Pike woke with a start, raced up the stairs and lit the lamp just in time.", "The next morning, the fishermen brought Marmalade a big, shiny fish as a thank-you present."],
    questions: [["What colour was the lighthouse?", ["white", "red", "grey"], 0, "retrieval"], ["Why did Mr Pike light the lamp every night?", ["so ships would not crash into the rocks", "so he could read", "to keep warm"], 0, "retrieval"], ["What problem happened on the stormy evening?", ["Mr Pike fell asleep and the lamp was dark.", "The cat was lost.", "The lamp broke."], 0, "summarising"], ["What does \"woke with a start\" mean?", ["woke up suddenly", "woke up slowly", "started to sleep"], 0, "vocabulary"], ["Why did the fishermen bring a fish?", ["to thank Marmalade for saving them", "because they had too many", "for Mr Pike's dinner"], 0, "inference"], ["Which word best describes Marmalade?", ["clever", "lazy", "grumpy"], 0, "inference"]],
    grammar: [["Which is an expanded noun phrase?", ["a big, shiny fish", "a fish", "fish swim"], 0], ["Which kind of sentence is \"Light the lamp!\"?", ["a command", "a question", "a statement"], 0]] },
  { id: "as8-2", title: "Hedgehogs", type: "Information", text: ["Hedgehogs are small, spiky mammals that live in gardens, parks and woods.", "A hedgehog has about 5,000 sharp spines on its back. When it is frightened, it rolls into a tight, prickly ball to protect itself.", "Hedgehogs are nocturnal. This means they sleep in the day and come out at night to look for food. They eat beetles, worms, slugs and caterpillars.", "In winter, when food is hard to find, hedgehogs hibernate. They build a nest of leaves and sleep until spring.", "You can help hedgehogs by leaving a small gap under your garden fence."],
    questions: [["Where do hedgehogs live?", ["in gardens, parks and woods", "in the sea", "in deserts"], 0, "retrieval"], ["What does a hedgehog do when it is frightened?", ["rolls into a ball", "runs up a tree", "hisses loudly"], 0, "retrieval"], ["What does \"nocturnal\" mean?", ["awake at night and asleep in the day", "living in water", "eating plants"], 0, "vocabulary"], ["Why do hedgehogs hibernate?", ["Food is hard to find in winter.", "They are bored.", "It is too hot."], 0, "inference"], ["How can people help hedgehogs?", ["leave a gap under the garden fence", "pick them up", "give them milk"], 0, "retrieval"], ["How is the text organised?", ["Each paragraph gives a different fact about hedgehogs.", "It tells a story in order.", "It gives instructions."], 0, "structure"]],
    grammar: [["Which list is written correctly?", ["beetles, worms, slugs and caterpillars", "beetles worms slugs and caterpillars", "beetles, worms, slugs, and, caterpillars"], 0], ["Which is an expanded noun phrase?", ["a tight, prickly ball", "a ball", "it rolls"], 0]] },
  { id: "as8-3", title: "The Magic Paint Pot", type: "Story", text: ["Ruby found a little pot of purple paint at the back of the art cupboard. On the lid were the words: Paint carefully!", "Ruby painted a butterfly on her paper. To her amazement, it fluttered off the page and flew around the classroom!", "Next, she painted a tiny kitten. It jumped down and curled up on her teacher's chair.", "\"What fun!\" thought Ruby, and she painted an enormous elephant.", "CRASH! The elephant stepped off the page and knocked over three tables. Ruby quickly painted a door, and the elephant squeezed through it and was gone.", "From then on, Ruby only painted small things."],
    questions: [["What colour was the paint?", ["purple", "red", "green"], 0, "retrieval"], ["What did the words on the lid say?", ["Paint carefully!", "Do not open!", "Magic paint!"], 0, "retrieval"], ["What did Ruby paint first?", ["a butterfly", "a kitten", "an elephant"], 0, "sequencing"], ["Why did Ruby paint a door?", ["to get the elephant out", "to make a house", "for fun"], 0, "inference"], ["What lesson did Ruby learn?", ["to paint carefully", "to paint faster", "to stop painting"], 0, "summarising"], ["What does \"to her amazement\" mean?", ["she was very surprised", "she was bored", "she was cross"], 0, "vocabulary"]],
    grammar: [["Which sentence is an exclamation?", ["What fun!", "Ruby found a pot.", "Did Ruby paint?"], 0], ["Which is an expanded noun phrase?", ["a little pot of purple paint", "paint", "she painted"], 0]] },
  { id: "as8-4", title: "Our Class Trip to the Farm", type: "Recount", text: ["On Tuesday, our class went on a trip to Green Meadow Farm.", "When we arrived, the farmer, Mrs Brown, showed us the cows, sheep, goats and pigs. We even fed the baby lambs with bottles of milk!", "After lunch, we went on a bumpy tractor ride around the fields. We saw rows of corn, carrots and potatoes growing.", "Before we left, Mrs Brown let us collect eggs from the hen house. I found three brown eggs!", "It was the best school trip ever. I can't wait to go again."],
    questions: [["What was the farm called?", ["Green Meadow Farm", "Brown Farm", "Sunny Farm"], 0, "retrieval"], ["What did the children feed the lambs?", ["bottles of milk", "carrots", "corn"], 0, "retrieval"], ["What happened after lunch?", ["a tractor ride", "feeding lambs", "collecting eggs"], 0, "sequencing"], ["What does \"bumpy\" tell us about the ride?", ["it went up and down and shook", "it was very smooth", "it was very slow"], 0, "vocabulary"], ["How does the writer feel about the trip?", ["They loved it.", "They were bored.", "They were scared."], 0, "inference"], ["What kind of text is this?", ["a recount of a real trip", "instructions", "a fairy tale"], 0, "structure"]],
    grammar: [["Which list has commas in the right places?", ["cows, sheep, goats and pigs", "cows sheep goats and pigs", "cows, sheep, goats, and, pigs"], 0], ["What kind of sentence is \"I can't wait to go again.\"?", ["a statement", "a question", "a command"], 0]] },
  { id: "as8-5", title: "The Shy Dragon", type: "Story", text: ["In a cave high in the mountains lived a small, shy dragon called Ember.", "The other dragons roared and breathed huge flames, but Ember could only make a tiny puff of smoke. The others laughed at her.", "One freezing winter night, the villagers below could not light their fires. Their houses were dark and cold.", "Ember crept down the mountain. Gently, she breathed her tiny flame onto each fireplace. One by one, the fires crackled into life.", "The next morning, the villagers left warm bread and honey outside Ember's cave. Ember wasn't laughed at ever again."],
    questions: [["Where did Ember live?", ["in a cave high in the mountains", "in the village", "by the sea"], 0, "retrieval"], ["Why did the other dragons laugh at Ember?", ["She could only make a tiny puff of smoke.", "She was too big.", "She could not fly."], 0, "retrieval"], ["What problem did the villagers have?", ["They could not light their fires.", "They had no food.", "Their houses fell down."], 0, "summarising"], ["Why was Ember's small flame perfect for the job?", ["She could light fires gently without burning the houses.", "It was very hot.", "It was colourful."], 0, "inference"], ["What does \"crept\" mean?", ["moved quietly and carefully", "ran loudly", "flew fast"], 0, "vocabulary"], ["What do the gifts show?", ["The villagers were grateful.", "The villagers were scared.", "The villagers were hungry."], 0, "inference"]],
    grammar: [["Which is an expanded noun phrase?", ["a small, shy dragon", "a dragon", "Ember flew"], 0], ["Which list is punctuated correctly?", ["warm bread, honey and milk", "warm bread honey and milk", "warm, bread, honey, and milk"], 0]] },
  { id: "as8-6", title: "The Kite", type: "Poem", text: ["My kite is a bird with a long, ribbon tail,", "It swoops and it soars like a ship in full sail.", "It dips to the left and it darts to the right,", "It tugs at the string with all of its might.", "Then the wind drops away, and the sky becomes still,", "And my kite floats down softly on top of the hill."],
    questions: [["What is the kite compared to first?", ["a bird", "a fish", "a cloud"], 0, "language"], ["What does the kite's tail look like?", ["a long ribbon", "a feather", "a rope"], 0, "retrieval"], ["What does \"soars\" mean?", ["flies high in the air", "falls down", "runs fast"], 0, "vocabulary"], ["Why does the kite float down at the end?", ["The wind drops away.", "The string breaks.", "It starts to rain."], 0, "inference"], ["Which word rhymes with \"still\"?", ["hill", "sail", "right"], 0, "language"], ["How does the mood change at the end?", ["from busy and exciting to calm", "from calm to scary", "it does not change"], 0, "summarising"]],
    grammar: [["Which is an expanded noun phrase?", ["a long, ribbon tail", "tail", "it soars"], 0], ["What kind of sentence would \"Hold the string tight!\" be?", ["a command", "a question", "a statement"], 0]] }
];

