ASSESS[9] = [
  { id: "as9-1", title: "The Treasure Map", type: "Story", text: ["While Leo was tidying his grandad's attic, he found an old, folded map tucked inside a book. A red X was drawn next to a tall tree beside a river.", "\"That's the oak tree at the bottom of the park!\" said Leo. He grabbed a spade, and he and Grandad set off.", "They counted ten steps from the tree towards the river, just as the map said. Then they started digging. The ground was hard, but they kept going.", "Clunk! The spade hit something metal. It was a rusty tin box. Inside were marbles, a toy car and a faded photo of a little boy.", "\"That's me!\" laughed Grandad. \"I buried this box sixty years ago, and I forgot all about it!\""],
    questions: [["Where did Leo find the map?", ["inside a book in the attic", "under his bed", "in the park"], 0, "retrieval"], ["What was drawn next to the X?", ["a tall tree beside a river", "a house", "a mountain"], 0, "retrieval"], ["What did they do after counting ten steps?", ["started digging", "went home", "climbed the tree"], 0, "sequencing"], ["What does \"rusty\" tell us about the box?", ["it was old and had been in the ground a long time", "it was new and shiny", "it was made of wood"], 0, "vocabulary"], ["Who was the little boy in the photo?", ["Grandad", "Leo", "Leo's dad"], 0, "inference"], ["How do you think Grandad felt when he saw the box?", ["surprised and happy", "angry", "frightened"], 0, "inference"]],
    grammar: [["Which verb is in the past tense?", ["found", "finds", "finding"], 0], ["Choose the word: \"The ground was hard, ___ they kept going.\"", ["but", "or", "because"], 0]] },
  { id: "as9-2", title: "Life Cycle of a Butterfly", type: "Information", text: ["Butterflies change their shape completely as they grow. This is called a life cycle, and it has four stages.", "First, a female butterfly lays tiny eggs on a leaf. After a few days, a caterpillar hatches from each egg.", "The caterpillar is always hungry. It eats and eats, growing bigger every day.", "Next, the caterpillar makes a hard case around itself, called a chrysalis. Inside, its body is changing.", "Finally, after a few weeks, a butterfly breaks out of the chrysalis. It dries its wings in the sun and flies away to find flowers. Soon, it will lay eggs of its own, and the cycle will begin again."],
    questions: [["How many stages does the life cycle have?", ["four", "two", "six"], 0, "retrieval"], ["Where are the eggs laid?", ["on a leaf", "in water", "in a nest"], 0, "retrieval"], ["What is a chrysalis?", ["a hard case the caterpillar makes", "a kind of leaf", "a baby butterfly"], 0, "vocabulary"], ["What happens straight after the caterpillar hatches?", ["It eats and grows.", "It makes a chrysalis.", "It flies away."], 0, "sequencing"], ["Why is it called a \"cycle\"?", ["It goes round and starts again.", "Butterflies ride bikes.", "It happens once."], 0, "inference"], ["Which words show the order of the stages?", ["First, Next, Finally", "hungry, hard, tiny", "eggs, leaf, sun"], 0, "structure"]],
    grammar: [["Which sentence is in the present progressive?", ["The caterpillar is eating a leaf.", "The caterpillar ate a leaf.", "The caterpillar eats leaves."], 0], ["Choose the word: \"It eats ___ eats.\"", ["and", "but", "or"], 0]] },
  { id: "as9-3", title: "Snow Day", type: "Story", text: ["When Maya woke up, everything was quiet. She pulled back the curtains and gasped. The whole street was white!", "\"School is closed today because of the snow,\" said Mum, smiling.", "Maya and her brother, Sami, were soon building a snowman in the garden. Sami was rolling the body while Maya was searching for stones for the eyes.", "Then a snowball flew over the fence and hit Sami on the back. Over the fence, their neighbour, Mr Jones, was laughing.", "\"Snowball fight!\" shouted Sami. They threw snowballs until their fingers were frozen. Then Mum called them in for hot chocolate."],
    questions: [["Why was everything quiet when Maya woke up?", ["Snow had covered everything.", "Everyone had gone out.", "It was the middle of the night."], 0, "inference"], ["Why was school closed?", ["because of the snow", "because it was Saturday", "because the teacher was ill"], 0, "retrieval"], ["What was Sami doing while Maya searched for stones?", ["rolling the body", "eating breakfast", "throwing snowballs"], 0, "retrieval"], ["Who threw the first snowball?", ["Mr Jones", "Maya", "Mum"], 0, "retrieval"], ["What does \"gasped\" show about Maya?", ["She was surprised.", "She was tired.", "She was bored."], 0, "inference"], ["What happened at the end?", ["They went in for hot chocolate.", "They went to school.", "The snow melted."], 0, "sequencing"]],
    grammar: [["Which sentence uses the past progressive?", ["Sami was rolling the body.", "Sami rolled the body.", "Sami rolls the body."], 0], ["Which word joins: \"Do you want milk ___ hot chocolate?\"", ["or", "and", "but"], 0]] },
  { id: "as9-4", title: "Our Amazing Bones", type: "Information", text: ["Your body has a skeleton made of more than 200 bones. Without it, you would flop on the floor like a jellyfish!", "Your skeleton does three important jobs. It holds you up, it protects the soft parts inside you, and it helps you to move.", "Your skull is like a helmet that protects your brain. Your ribs form a cage around your heart and lungs.", "Bones are living things, and they grow as you grow. To keep them strong, you need to eat foods like milk, cheese and yoghurt, and you need to exercise."],
    questions: [["How many bones does a body have?", ["more than 200", "about 20", "exactly 100"], 0, "retrieval"], ["What protects your brain?", ["your skull", "your ribs", "your heart"], 0, "retrieval"], ["What do your ribs protect?", ["your heart and lungs", "your brain", "your legs"], 0, "retrieval"], ["What would happen without a skeleton?", ["You would flop on the floor.", "You would grow taller.", "You would run faster."], 0, "inference"], ["Why does the writer compare the skull to a helmet?", ["Both protect your head.", "Both are round.", "Both are made of plastic."], 0, "language"], ["How can you keep your bones strong?", ["eat dairy foods and exercise", "sleep all day", "eat sweets"], 0, "summarising"]],
    grammar: [["Which verb is in the present tense?", ["grow", "grew", "growed"], 0], ["Choose the word: \"Bones are hard, ___ they are alive.\"", ["but", "or", "so"], 0]] },
  { id: "as9-5", title: "The Missing Cake", type: "Story", text: ["Dad had baked a chocolate cake for Granny's birthday. He left it on the kitchen table and went to fetch the candles.", "When he came back, there was a big bite missing from the cake!", "Dad looked at Ella. Her hands were clean. He looked at Max. His face was clean too.", "Then Dad heard a noise under the table. Buster, the family dog, was licking his lips, and he had chocolate all over his nose.", "\"Buster!\" said Dad. Everyone laughed, even Dad. They put the candles on the other side of the cake, and Granny never knew."],
    questions: [["Why did Dad bake the cake?", ["for Granny's birthday", "for a party at school", "for his lunch"], 0, "retrieval"], ["Why did Dad leave the kitchen?", ["to fetch the candles", "to answer the door", "to walk the dog"], 0, "retrieval"], ["Why did Dad look at Ella's hands and Max's face?", ["to look for clues about who ate the cake", "to check they were washed", "to see if they were cold"], 0, "inference"], ["How did Dad find out who did it?", ["He saw chocolate on Buster's nose.", "Ella told him.", "Granny saw it."], 0, "retrieval"], ["Why did they put the candles on the other side?", ["to hide the missing bite", "because it looked nicer", "because there was no room"], 0, "inference"], ["What is the story mostly about?", ["finding out who ate the cake", "baking a cake", "a birthday party"], 0, "summarising"]],
    grammar: [["Which verb is in the past tense?", ["baked", "bake", "baking"], 0], ["Which sentence uses the past progressive?", ["Buster was licking his lips.", "Buster licked his lips.", "Buster licks his lips."], 0]] },
  { id: "as9-6", title: "The Busy Street", type: "Poem", text: ["The buses are rumbling, the taxis are beeping,", "The baby in the pram is peacefully sleeping.", "The baker is baking, the window cleaner's wiping,", "The pigeons are pecking, the starlings are piping.", "The shoppers are rushing with bags full of things,", "But the baby sleeps on, while the whole city sings."],
    questions: [["What are the taxis doing?", ["beeping", "rumbling", "singing"], 0, "retrieval"], ["Who is sleeping?", ["the baby", "the baker", "the pigeons"], 0, "retrieval"], ["What does \"rumbling\" describe?", ["a deep, low noise", "a soft whisper", "a bright light"], 0, "vocabulary"], ["What is surprising about the baby?", ["It sleeps even though the street is so noisy.", "It is shopping.", "It is singing."], 0, "inference"], ["Why does the poet say the city \"sings\"?", ["All the busy sounds together are like music.", "People are in a choir.", "There is a concert."], 0, "language"], ["Which word rhymes with \"beeping\"?", ["sleeping", "wiping", "things"], 0, "language"]],
    grammar: [["Which verb is in the present progressive?", ["are rushing", "rushed", "rush"], 0], ["Which word in the last line joins two ideas?", ["while", "the", "sings"], 0]] }
];
ASSESS[10] = [
  { id: "as10-1", title: "The Brave Little Boat", type: "Story", text: ["Pip was the smallest boat in the harbour. The big ships often teased him. \"You're too tiny to be useful,\" they said.", "One night, a terrible storm blew in. A fishing boat was trapped between the rocks at the edge of the bay, and the big ships couldn't reach it because the water was too shallow.", "\"I can go,\" said Pip bravely. He chugged out into the crashing waves. When he reached the fishing boat, he threw it a rope and pulled with all his strength.", "Slowly, the fishing boat slid free. Pip towed it back to the harbour, where everyone was waiting.", "That night, nobody called Pip tiny. They called him a hero."],
    questions: [["Why did the big ships tease Pip?", ["He was the smallest boat.", "He was slow.", "He was old."], 0, "retrieval"], ["Why couldn't the big ships help?", ["The water was too shallow.", "They were asleep.", "They were scared of the storm."], 0, "retrieval"], ["What did Pip throw to the fishing boat?", ["a rope", "a net", "a lifebelt"], 0, "retrieval"], ["What does \"shallow\" mean?", ["not deep", "very cold", "very rough"], 0, "vocabulary"], ["Why was being small useful in the end?", ["Pip could go where the big ships couldn't.", "Pip was faster.", "Pip was stronger."], 0, "inference"], ["What is the message of the story?", ["Small things can be very important.", "Storms are dangerous.", "Big ships are best."], 0, "summarising"]],
    grammar: [["Which word joins the ideas: \"The ships couldn't reach it ___ the water was too shallow.\"", ["because", "but", "or"], 0], ["What is the short form of \"could not\"?", ["couldn't", "could'nt", "coudn't"], 0]] },
  { id: "as10-2", title: "Why Do We Have Seasons?", type: "Information", text: ["Have you noticed that summer days are long and hot, while winter days are short and cold? This happens because of the way the Earth moves.", "The Earth travels around the Sun once every year. It is also tilted, which means it leans to one side.", "When our part of the Earth leans towards the Sun, we get more sunlight, so it is summer. When it leans away from the Sun, we get less sunlight, so it is winter.", "Spring and autumn happen in between, when the days are not too hot and not too cold.", "If you live near the middle of the Earth, the seasons hardly change at all!"],
    questions: [["How long does the Earth take to travel around the Sun?", ["one year", "one day", "one month"], 0, "retrieval"], ["What does \"tilted\" mean?", ["leaning to one side", "spinning fast", "standing still"], 0, "vocabulary"], ["Why is it summer when our part of the Earth leans towards the Sun?", ["We get more sunlight.", "We are further away.", "The Sun gets bigger."], 0, "inference"], ["When do spring and autumn happen?", ["in between summer and winter", "only at night", "every day"], 0, "retrieval"], ["Where do the seasons hardly change?", ["near the middle of the Earth", "near the North Pole", "on mountains"], 0, "retrieval"], ["What is the text mostly about?", ["why we have seasons", "how to stay warm", "the planets"], 0, "summarising"]],
    grammar: [["Which word starts a part that gives a reason: \"It is summer ___ we get more sunlight.\"", ["because", "or", "but"], 0], ["Which word has the suffix -ly?", ["hardly", "hard", "harder"], 0]] },
  { id: "as10-3", title: "Nadia's New School", type: "Story", text: ["On her first day at her new school, Nadia's tummy felt full of butterflies. She didn't know anybody, and everyone else seemed to have a friend.", "At break time, she sat on a bench on her own. She pretended to read her book, but really she was watching the other children play.", "Then a girl with a red hair band sat down next to her. \"I'm Kiki,\" she said. \"Do you want to play skipping with us?\"", "Nadia nodded shyly. Kiki's friends were kind and patient, and by the end of break, Nadia was laughing.", "That evening, Mum asked how her day had been. \"It was wonderful,\" said Nadia. \"I've made a friend called Kiki.\""],
    questions: [["How did Nadia feel at the start of the day?", ["nervous", "excited", "angry"], 0, "inference"], ["What does \"butterflies\" in her tummy mean?", ["a nervous feeling", "she was hungry", "she ate a butterfly"], 0, "language"], ["Why did Nadia pretend to read?", ["She was alone and felt shy.", "She loved her book.", "Her teacher told her to."], 0, "inference"], ["What did Kiki ask Nadia?", ["if she wanted to play skipping", "what her name was", "where she lived"], 0, "retrieval"], ["How did Nadia's feelings change during the day?", ["from nervous to happy", "from happy to sad", "they stayed the same"], 0, "summarising"], ["Which word describes Kiki?", ["kind", "unkind", "lazy"], 0, "inference"]],
    grammar: [["What does the apostrophe show in \"Kiki's friends\"?", ["the friends belong to Kiki", "a letter is missing", "there are many Kikis"], 0], ["Which word has the suffix -ful?", ["wonderful", "wonder", "wondering"], 0]] },
  { id: "as10-4", title: "How to Look After a Goldfish", type: "Instructions", text: ["Goldfish make great pets if you look after them carefully.", "Tank: Give your goldfish a big tank with a filter. A small bowl is not enough, because goldfish need lots of clean water.", "Food: Feed your fish a small pinch of fish flakes once or twice a day. Don't give too much, because uneaten food makes the water dirty.", "Cleaning: Every week, change some of the water. Never use water straight from the tap unless you have treated it first.", "If you follow these steps, your goldfish could live for more than ten years!"],
    questions: [["Why is a small bowl not enough?", ["Goldfish need lots of clean water.", "Bowls are too heavy.", "Goldfish like to hide."], 0, "retrieval"], ["How often should you feed a goldfish?", ["once or twice a day", "once a week", "ten times a day"], 0, "retrieval"], ["Why shouldn't you give too much food?", ["Uneaten food makes the water dirty.", "The fish will run away.", "Food is expensive."], 0, "retrieval"], ["What do the labels at the start of each part, such as \"Tank:\" and \"Food:\", do?", ["show what each part is about", "tell a story", "list the fish's names"], 0, "structure"], ["What might happen if you never cleaned the tank?", ["The fish could become ill.", "The fish would grow faster.", "Nothing would happen."], 0, "prediction"], ["How long could a goldfish live?", ["more than ten years", "one week", "one month"], 0, "retrieval"]],
    grammar: [["Which word in \"Don't give too much\" uses an apostrophe for a missing letter?", ["Don't", "give", "much"], 0], ["Which word starts a part that says when: \"___ you follow these steps, your fish will be happy.\"", ["If", "But", "Or"], 0]] },
  { id: "as10-5", title: "The Clever Crow", type: "Fable", text: ["One hot summer's day, a thirsty crow flew over fields that were dry and dusty. At last, she spotted a jug of water in a garden.", "When she landed beside it, she found that there was only a little water at the bottom. Her beak was too short to reach it.", "The crow did not give up. She looked around and saw a pile of pebbles. One by one, she picked up the pebbles and dropped them into the jug.", "Slowly, the water rose higher and higher until it reached the top. The crow drank happily.", "Sometimes, when we think carefully, we can solve problems that seem impossible."],
    questions: [["Why was the crow looking for water?", ["She was thirsty.", "She wanted a bath.", "She was lost."], 0, "retrieval"], ["What was the problem with the jug?", ["The water was too low to reach.", "It was empty.", "It was broken."], 0, "summarising"], ["What did the crow drop into the jug?", ["pebbles", "leaves", "sticks"], 0, "retrieval"], ["Why did the water rise?", ["The pebbles filled up the space.", "It rained.", "Someone poured more in."], 0, "inference"], ["What does \"did not give up\" tell us about the crow?", ["She kept trying.", "She was lazy.", "She flew away."], 0, "inference"], ["What is the moral of the fable?", ["Thinking carefully can solve hard problems.", "Always carry water.", "Crows are greedy."], 0, "summarising"]],
    grammar: [["Which word starts a part that tells us when: \"___ she landed, she found the jug.\"", ["When", "And", "Or"], 0], ["Which word has the suffix -ly?", ["slowly", "slow", "slower"], 0]] },
  { id: "as10-6", title: "If I Were a Bird", type: "Poem", text: ["If I were a bird, I'd fly so high,", "I'd paint my name across the sky.", "I'd race the clouds and chase the rain,", "And sit on every weather vane.", "But when the evening stars came out,", "I'd fly back home, there's not a doubt,", "Because however far I roam,", "There's no nest sweeter than my home."],
    questions: [["What would the poet do if they were a bird?", ["fly high and race the clouds", "swim in the sea", "dig holes"], 0, "retrieval"], ["What does \"I'd paint my name across the sky\" suggest?", ["flying in patterns, like writing in the sky", "using real paint", "drawing a picture"], 0, "language"], ["When would the bird fly home?", ["when the evening stars came out", "in the morning", "when it rained"], 0, "retrieval"], ["What does \"roam\" mean?", ["travel around", "sleep", "sing"], 0, "vocabulary"], ["What is the message of the last two lines?", ["Home is the best place of all.", "Birds like rain.", "Flying is tiring."], 0, "summarising"], ["Which word rhymes with \"roam\"?", ["home", "rain", "doubt"], 0, "language"]],
    grammar: [["What is the long form of \"I'd\"?", ["I would", "I did not", "I had to"], 0], ["Which word joins a reason in line 7?", ["Because", "far", "roam"], 0]] }
];

