ASSESS[11] = [
  { id: "as11-1", title: "The Secret Tunnel", type: "Story", text: ["Behind the bookcase in Great-Aunt Iris's study, there was a small wooden door that nobody ever opened. While the grown-ups were drinking tea one rainy afternoon, Adam and his cousin Bea decided to investigate.", "The door creaked open onto a narrow tunnel. Bea switched on her torch, and they crept inside. Cobwebs brushed their faces, and the air smelled of damp earth.", "After a while, the tunnel sloped upwards and ended at a trapdoor. Adam pushed it open and blinked in surprise. They were standing in the old summer house at the bottom of the garden!", "That evening, Great-Aunt Iris smiled when they told her. \"My brother and I used that tunnel when we were your age,\" she said. \"Now it's your turn to keep the secret.\""],
    questions: [["Where was the small wooden door?", ["behind the bookcase in the study", "under the stairs", "in the garden"], 0, "retrieval"], ["Why did the children explore while the grown-ups drank tea?", ["so nobody would stop them", "because they were bored of tea", "because it was sunny"], 0, "inference"], ["Which words help you imagine the tunnel?", ["cobwebs, damp earth, narrow", "bright, sunny, warm", "noisy, crowded, busy"], 0, "language"], ["Where did the tunnel lead?", ["to the summer house", "to a cave", "to the attic"], 0, "retrieval"], ["What does \"investigate\" mean?", ["find out about something", "hide something", "break something"], 0, "vocabulary"], ["How does the story end?", ["The children are trusted with the secret.", "The children get into trouble.", "The tunnel is closed for ever."], 0, "summarising"]],
    grammar: [["Which word in the first paragraph tells us when?", ["While", "Behind", "nobody"], 0], ["Choose a or an: \"They found ___ old trapdoor.\"", ["an", "a"], 0]] },
  { id: "as11-2", title: "The Great Wall of China", type: "Information", text: ["The Great Wall of China is one of the most famous structures in the world. It winds across mountains, deserts and grasslands in northern China.", "The wall was not built all at once. Different emperors added to it over more than two thousand years. Its main purpose was to protect China from invaders from the north.", "Building the wall was extremely hard work. Millions of soldiers, farmers and prisoners carried stone, brick and earth by hand. Many workers died because of the harsh conditions.", "Today, the wall is a popular place for visitors. Although some parts have crumbled, other parts have been carefully repaired. If you walk along it, you can see watchtowers where soldiers once lit fires to send warning signals."],
    questions: [["Where is the Great Wall?", ["northern China", "southern China", "India"], 0, "retrieval"], ["What was the wall's main purpose?", ["to protect China from invaders", "to keep animals in", "to mark a road"], 0, "retrieval"], ["How long did it take to build?", ["more than two thousand years", "ten years", "one hundred years"], 0, "retrieval"], ["Why was building the wall so dangerous?", ["The work was very hard and conditions were harsh.", "There were wild animals.", "It was always raining."], 0, "inference"], ["What does \"harsh\" mean?", ["very difficult and unpleasant", "gentle and easy", "warm and sunny"], 0, "vocabulary"], ["What were the watchtowers used for?", ["sending warning signals with fire", "storing food", "sleeping"], 0, "retrieval"]],
    grammar: [["Which word in \"Many workers died because of the harsh conditions\" introduces a reason?", ["because", "Many", "harsh"], 0], ["Which word is a conjunction?", ["Although", "wall", "today"], 0]] },
  { id: "as11-3", title: "Kai and the Kite Festival", type: "Story", text: ["Every spring, Kai's town held a kite festival on the beach. This year, Kai had made his own kite: a bright blue fish with a long, silver tail.", "Before the competition began, the wind dropped completely. All around Kai, children were running up and down the sand, but their kites kept crashing back to the ground.", "Kai waited patiently. He watched the flags on the lifeguard hut. Soon, he noticed them begin to flutter. Then he ran.", "His fish leapt into the sky and swam higher and higher until it was a tiny blue dot above the waves. The judges looked up and clapped.", "Kai did not win first prize, but he won the prize for the best homemade kite. He was so proud that he slept with his kite beside his bed."],
    questions: [["What did Kai's kite look like?", ["a blue fish with a silver tail", "a red dragon", "a yellow bird"], 0, "retrieval"], ["What happened before the competition began?", ["The wind dropped.", "It started to rain.", "Kai's kite broke."], 0, "sequencing"], ["Why did Kai watch the flags?", ["to see when the wind came back", "because they were pretty", "to find the judges"], 0, "inference"], ["What does \"patiently\" tell us about Kai?", ["he waited calmly without rushing", "he was angry", "he gave up"], 0, "vocabulary"], ["How does the writer show the kite flying high?", ["it became a tiny blue dot", "it made a loud noise", "it changed colour"], 0, "language"], ["How did Kai feel about his prize?", ["very proud", "disappointed", "embarrassed"], 0, "inference"]],
    grammar: [["Which word is an adverb that tells us when?", ["Soon", "blue", "kite"], 0], ["Which phrase starts with a preposition of time?", ["Before the competition", "the long silver tail", "Kai ran"], 0]] },
  { id: "as11-4", title: "Keeping Teeth Healthy", type: "Explanation", text: ["Your teeth have to last a lifetime, so it is important to look after them. But why do teeth sometimes go wrong?", "Our mouths are full of tiny living things called bacteria. When we eat sugary food, the bacteria feed on the sugar and make acid. The acid slowly eats away at the hard outer layer of our teeth, called enamel. Over time, this can make a hole, or cavity.", "Brushing your teeth twice a day removes the bacteria and food. Toothpaste with fluoride also makes enamel stronger.", "Cutting down on sweets and fizzy drinks helps too, because the bacteria have less sugar to feed on.", "Finally, visiting the dentist regularly means that any problems can be found early, before they become painful."],
    questions: [["What are bacteria?", ["tiny living things", "a kind of toothpaste", "parts of a tooth"], 0, "vocabulary"], ["What do bacteria make when they feed on sugar?", ["acid", "enamel", "fluoride"], 0, "retrieval"], ["What is enamel?", ["the hard outer layer of a tooth", "a sweet", "a dentist's tool"], 0, "retrieval"], ["What does fluoride do?", ["makes enamel stronger", "feeds bacteria", "makes holes"], 0, "retrieval"], ["Why does cutting down on sweets help?", ["The bacteria have less sugar to feed on.", "Sweets are expensive.", "Sweets make teeth grow."], 0, "inference"], ["How is this text organised?", ["It explains the problem and then how to prevent it.", "It tells a story about a dentist.", "It is a list of rules with no reasons."], 0, "structure"]],
    grammar: [["Which word introduces a reason in the fourth paragraph?", ["because", "too", "less"], 0], ["Choose a or an: \"Visit ___ dentist every six months.\"", ["a", "an"], 0]] },
  { id: "as11-5", title: "The Fox and the Stork", type: "Fable", text: ["Once, a fox invited a stork to dinner. The fox, who liked to play tricks, served soup in a wide, flat dish.", "The fox lapped up his soup easily, but the stork's long, thin beak could only dip into the dish. She went home hungry.", "\"Thank you,\" said the stork politely. \"Now you must come to dinner with me.\"", "The next week, the fox arrived at the stork's house, feeling very hungry. The stork served a delicious stew in a tall jar with a narrow neck.", "The stork's beak reached easily to the bottom, but the fox could only lick the outside of the jar. This time, it was the fox who went home hungry.", "Moral: Do not play tricks on others unless you are ready to have the same trick played on you."],
    questions: [["What did the fox serve the soup in?", ["a wide, flat dish", "a tall jar", "a cup"], 0, "retrieval"], ["Why couldn't the stork eat the soup?", ["Her beak was too long and thin.", "She did not like soup.", "It was too hot."], 0, "inference"], ["What did the stork serve?", ["stew in a tall jar", "soup in a dish", "fish on a plate"], 0, "retrieval"], ["Why did the stork use a tall jar?", ["to play the same kind of trick on the fox", "because she had no dishes", "to keep the stew hot"], 0, "inference"], ["What does \"politely\" suggest about the stork?", ["She stayed calm and well-mannered.", "She was rude.", "She was scared."], 0, "vocabulary"], ["What is a moral?", ["a lesson the story teaches", "the title", "the main character"], 0, "structure"]],
    grammar: [["Which word tells us when: \"___ week, the fox arrived.\"", ["The next", "Because", "Although"], 0], ["Choose a or an: \"The fox was ___ animal who liked tricks.\"", ["an", "a"], 0]] },
  { id: "as11-6", title: "The Sea at Night", type: "Poem", text: ["When the sun has slipped below the sky,", "And the gulls have folded their wings to sleep,", "The sea keeps whispering, low and shy,", "Its secrets from the dark and deep.", "It hums to the harbour, it sighs to the sand,", "It rocks the boats like a gentle hand,", "And all through the night, till the morning is grey,", "It sings the whole sleeping town away."],
    questions: [["What have the gulls done?", ["folded their wings to sleep", "flown away", "started to sing"], 0, "retrieval"], ["What does the sea keep doing?", ["whispering", "shouting", "freezing"], 0, "retrieval"], ["What does \"like a gentle hand\" suggest?", ["the sea rocks the boats softly and kindly", "the sea is rough", "someone is holding the boats"], 0, "language"], ["Why does the poet say the sea is \"shy\"?", ["its sounds are quiet and soft", "it hides behind rocks", "it is scared of the dark"], 0, "language"], ["What time of day does the poem end?", ["morning", "midday", "evening"], 0, "sequencing"], ["What is the mood of the poem?", ["calm and peaceful", "frightening", "angry"], 0, "inference"]],
    grammar: [["Which word in line 1 is a conjunction that tells us when?", ["When", "sun", "below"], 0], ["Which phrase tells us how long the sea sings?", ["all through the night", "the harbour", "the boats"], 0]] }
];
ASSESS[12] = [
  { id: "as12-1", title: "The Robot Who Wanted to Paint", type: "Story", text: ["Bolt was a factory robot. Every day for ten years, he had fitted the same bolts onto the same cars. He had never complained, and he had never made a mistake.", "One morning, a gust of wind blew a newspaper through the factory door. It landed open at a picture of a sunset, painted in swirls of orange and pink. Bolt had never seen anything so beautiful.", "That night, when the factory was empty, Bolt dipped his metal finger into a pot of orange oil paint and drew a wobbly sun on the wall.", "\"Who has done this?\" demanded the manager the next day. Bolt's lights flickered nervously. \"I have,\" he admitted.", "The manager stared at the painting for a long time. Then, to everyone's surprise, she smiled. \"It's rather good,\" she said. \"Perhaps you've found a new job.\""],
    questions: [["What had Bolt done every day for ten years?", ["fitted bolts onto cars", "painted pictures", "cleaned the factory"], 0, "retrieval"], ["What did the newspaper picture show?", ["a sunset", "a car", "a robot"], 0, "retrieval"], ["Why did Bolt paint at night?", ["so nobody would see him", "because he worked in the day", "because the paint was cheaper"], 0, "inference"], ["What does \"flickered nervously\" show about Bolt?", ["He was worried he was in trouble.", "His battery was low.", "He was excited."], 0, "language"], ["What do you think the manager's \"new job\" for Bolt might be?", ["painting", "fitting more bolts", "leaving the factory"], 0, "prediction"], ["What is the main message of the story?", ["It's never too late to discover something you love.", "Robots should not paint.", "Factories are boring."], 0, "summarising"]],
    grammar: [["Which verb is in the present perfect?", ["has done", "did", "does"], 0], ["Which sentence uses inverted commas correctly?", ["\"I have,\" he admitted.", "I have, he admitted.", "\"I have, he admitted."], 0]] },
  { id: "as12-2", title: "Volcanoes of Iceland", type: "Information", text: ["Iceland is a small island country in the North Atlantic Ocean. It is sometimes called \"the land of fire and ice\", because it has huge glaciers and more than thirty active volcanoes.", "Iceland sits on top of a crack in the Earth's crust, where two enormous plates of rock are slowly moving apart. As they pull away from each other, melted rock called magma rises up and erupts as lava.", "Living near volcanoes has some advantages. Icelanders use the heat underground to warm their homes and make electricity. Hot water from the ground fills outdoor swimming pools, even in the snow.", "However, eruptions can also cause problems. In 2010, ash from a volcano called Eyjafjallajökull spread across Europe, and thousands of flights were cancelled."],
    questions: [["Why is Iceland called \"the land of fire and ice\"?", ["It has glaciers and active volcanoes.", "It is very cold and very hot every day.", "It has many fireworks."], 0, "inference"], ["How many active volcanoes does Iceland have?", ["more than thirty", "two", "about five"], 0, "retrieval"], ["What is magma?", ["melted rock under the ground", "ice", "volcanic ash in the sky"], 0, "vocabulary"], ["Give one advantage of living near volcanoes.", ["heat to warm homes", "cancelled flights", "lava flows"], 0, "retrieval"], ["What happened in 2010?", ["Volcanic ash cancelled thousands of flights.", "A new island formed.", "All the glaciers melted."], 0, "retrieval"], ["Why does the last paragraph begin with \"However\"?", ["to introduce the problems after the advantages", "to start a story", "to give an example"], 0, "structure"]],
    grammar: [["Which word belongs to the same word family as \"volcano\"?", ["volcanic", "voice", "valley"], 0], ["Which verb form is the present perfect?", ["have used", "used", "use"], 0]] },
  { id: "as12-3", title: "The Last Bus Home", type: "Story", text: ["Hana checked her watch for the third time. The last bus home was due at nine o'clock, and it was already five past.", "\"It's never late,\" she muttered to herself. The bus stop was empty, and the street was silent except for the buzzing of the streetlight.", "Just then, a car pulled up. A woman leaned out of the window. \"Are you waiting for the number 12?\" she asked. \"It's broken down by the bridge. Shall I call your parents?\"", "Hana remembered what her mum always told her: never get into a stranger's car. \"No, thank you,\" she said politely. \"I'll ring them myself.\"", "Ten minutes later, her dad's familiar blue car came round the corner. Hana had never been so pleased to see it."],
    questions: [["What time was the last bus due?", ["nine o'clock", "five past nine", "ten o'clock"], 0, "retrieval"], ["Why was the bus late?", ["It had broken down by the bridge.", "There was traffic.", "The driver was ill."], 0, "retrieval"], ["How was Hana feeling while she waited?", ["worried", "sleepy", "excited"], 0, "inference"], ["Why did Hana refuse the woman's offer?", ["She remembered not to get into a stranger's car.", "She didn't like the woman.", "She wanted to walk."], 0, "inference"], ["What does \"familiar\" mean?", ["well known to her", "new and shiny", "very fast"], 0, "vocabulary"], ["Which word best describes Hana?", ["sensible", "careless", "rude"], 0, "inference"]],
    grammar: [["Which sentence is punctuated correctly?", ["\"I'll ring them myself,\" said Hana.", "I'll ring them myself, said Hana.", "\"I'll ring them myself, said Hana.\""], 0], ["Which verb is in the present perfect?", ["has broken", "broke", "breaks"], 0]] },
  { id: "as12-4", title: "Should Children Have Pets?", type: "Discussion", text: ["Many children dream of having a pet. But is having a pet a good idea?", "Some people believe pets are very good for children. Caring for an animal teaches responsibility, because the pet depends on you for food, water and exercise. Pets can also be wonderful companions, and studies have shown that stroking an animal can help people feel calmer.", "On the other hand, pets need a great deal of time and money. Dogs must be walked every day, whatever the weather, and visits to the vet can be expensive. Some children lose interest after a few weeks, leaving the work to their parents.", "In conclusion, a pet can bring a family a lot of joy, but only if everyone is ready for the responsibility it brings."],
    questions: [["Give one reason pets are good for children.", ["They teach responsibility.", "They are free.", "They need no care."], 0, "retrieval"], ["What can stroking an animal do?", ["help people feel calmer", "make pets grow", "cost money"], 0, "retrieval"], ["Give one reason against having a pet.", ["Pets need time and money.", "Pets are always quiet.", "Pets make you calm."], 0, "retrieval"], ["What does \"companions\" mean?", ["friends who keep you company", "toys", "neighbours"], 0, "vocabulary"], ["What does \"On the other hand\" show?", ["the writer is now giving the opposite view", "the writer is finishing", "a new story is starting"], 0, "structure"], ["What is the writer's conclusion?", ["Pets are good if the family is ready for the responsibility.", "No child should have a pet.", "Every child must have a dog."], 0, "summarising"]],
    grammar: [["Which word belongs to the word family of \"responsible\"?", ["responsibility", "response", "respect"], 0], ["Which verb is in the present perfect?", ["have shown", "showed", "shows"], 0]] },
  { id: "as12-5", title: "The Girl Who Talked to Trees", type: "Story", text: ["In a village at the edge of a great forest lived a girl called Selin, who believed that trees could talk.", "\"Trees don't talk,\" laughed the other children. But every day after school, Selin sat beneath the oldest oak and listened.", "One summer, men arrived with saws to clear the forest for a new road. The villagers shrugged. \"We need the road,\" they said.", "Selin ran to the oak. \"What should I do?\" she whispered. The leaves rustled, and a single acorn dropped into her hand.", "The next morning, Selin stood in front of the saws holding a sign: This oak has lived for 400 years. Please let it live for 400 more. One by one, the villagers came and stood beside her.", "The road was built, but it curved gently around the forest. And the old oak still stands there today."],
    questions: [["What did Selin believe?", ["that trees could talk", "that roads were bad", "that acorns were magic"], 0, "retrieval"], ["Why did the men come to the forest?", ["to clear it for a new road", "to plant trees", "to look for Selin"], 0, "retrieval"], ["What did the villagers think at first?", ["that the road was needed", "that the forest must be saved", "that Selin was right"], 0, "retrieval"], ["What made the villagers change their minds?", ["Selin's brave stand and her sign", "the acorn", "the men left"], 0, "inference"], ["What does \"curved gently around the forest\" tell us?", ["The road was built without cutting down the forest.", "The road was very short.", "The road went through the oak."], 0, "inference"], ["What is the theme of the story?", ["One brave person can make a difference.", "Roads are dangerous.", "Trees can really talk."], 0, "summarising"]],
    grammar: [["Which sentence uses inverted commas correctly?", ["\"What should I do?\" she whispered.", "What should I do? she whispered.", "\"What should I do? she whispered."], 0], ["Which word is in the same word family as \"village\"?", ["villagers", "vile", "valley"], 0]] },
  { id: "as12-6", title: "Moving House", type: "Poem", text: ["The boxes are stacked to the ceiling,", "The walls have gone bare and white,", "And there's a strange, echoing feeling,", "In the room where I slept last night.", "I've counted the cracks on the ceiling,", "I've measured my height on the door,", "And I've left a small note for the next child:", "Be happy. I was, here, before."],
    questions: [["What is stacked to the ceiling?", ["boxes", "books", "chairs"], 0, "retrieval"], ["Why does the room have an \"echoing feeling\"?", ["It is empty now.", "It is full of people.", "There is music playing."], 0, "inference"], ["What did the child measure on the door?", ["their height", "the cracks", "the boxes"], 0, "retrieval"], ["Who is the note for?", ["the next child who will live there", "the child's parents", "a friend"], 0, "retrieval"], ["How does the child feel about leaving?", ["a little sad but has happy memories", "angry", "excited and glad to go"], 0, "inference"], ["Which word rhymes with \"ceiling\"?", ["feeling", "white", "door"], 0, "language"]],
    grammar: [["Which verb is in the present perfect?", ["I've counted", "I count", "I counted"], 0], ["What does the apostrophe in \"I've\" show?", ["letters are missing", "something belongs to someone", "there are many"], 0]] }
];

/* ASSESSMENT TEXTS · BROWN (13) and GREY (14) · Year 4 */
ASSESS[13] = [
  { id: "as13-1", title: "The Clockmaker's Apprentice", type: "Story", text: ["In a narrow street of the old city stood a tiny shop crammed with clocks of every shape and size. It belonged to Mr Albescu, a clockmaker with silver spectacles and hands that never stopped moving.", "For a whole year, Elena had swept his floors and watched him work. She longed to mend a clock herself, but he always said, \"Not yet.\"", "Early one winter morning, Mr Albescu was ill in bed, and the mayor arrived in a panic. The great clock on the town hall had stopped, and the festival began at noon.", "With trembling hands, Elena climbed the tower. Inside the clock, she found a bent wheel no bigger than a coin. Carefully, just as she had seen Mr Albescu do a hundred times, she straightened it.", "At exactly twelve o'clock, the bells rang out across the square. In his bed, Mr Albescu heard them and smiled. \"Yes,\" he whispered. \"Now.\""],
    questions: [["What was Mr Albescu's shop full of?", ["clocks", "books", "toys"], 0, "retrieval"], ["What had Elena done for a whole year?", ["swept the floors and watched him work", "mended clocks", "worked for the mayor"], 0, "retrieval"], ["Why was the mayor in a panic?", ["The town hall clock had stopped before the festival.", "The shop was closed.", "Mr Albescu was missing."], 0, "inference"], ["What does \"With trembling hands\" tell us about Elena?", ["She was nervous.", "She was cold.", "She was angry."], 0, "language"], ["How did Elena know how to fix the clock?", ["She had watched Mr Albescu many times.", "She read a book.", "The mayor told her."], 0, "inference"], ["What does Mr Albescu mean when he whispers \"Now\"?", ["Elena is finally ready to mend clocks.", "It is time for lunch.", "He wants to get up."], 0, "inference"]],
    grammar: [["Which is a fronted adverbial?", ["Early one winter morning,", "the great clock", "she straightened it"], 0], ["Which is an expanded noun phrase with a preposition?", ["a clockmaker with silver spectacles", "a clockmaker", "he smiled"], 0]] },
  { id: "as13-2", title: "Life in an Anglo-Saxon Village", type: "Information", text: ["After the Romans left Britain, around 1,600 years ago, people from northern Europe called the Anglo-Saxons began to settle here. Most of them were farmers.", "Anglo-Saxon villages were small, usually with just a few families. Their houses were made of wood, with roofs of thatched straw. Inside, there was one main room with a fire in the middle for cooking and warmth. Because there was no chimney, the smoke escaped through a hole in the roof.", "Everyone in the family worked. Men ploughed the fields and hunted, while women spun wool, wove cloth and made butter and cheese. Children helped by looking after the animals and collecting firewood.", "In the evenings, people gathered in the hall of the local lord to eat, drink and listen to storytellers. Many of their stories, like the poem Beowulf, are still read today."],
    questions: [["Who were the Anglo-Saxons?", ["people from northern Europe who settled in Britain", "Roman soldiers", "Vikings"], 0, "retrieval"], ["What were Anglo-Saxon roofs made of?", ["thatched straw", "slate", "tiles"], 0, "retrieval"], ["How did smoke leave the house?", ["through a hole in the roof", "through a chimney", "through the door"], 0, "retrieval"], ["What did children do to help?", ["looked after animals and collected firewood", "ploughed fields", "wove cloth"], 0, "retrieval"], ["What does \"settle\" mean here?", ["make a home and live in a place", "sit down", "end an argument"], 0, "vocabulary"], ["What does the last paragraph tell us about Anglo-Saxon life?", ["Stories and entertainment were important.", "They never rested.", "They lived alone."], 0, "summarising"]],
    grammar: [["Which is a fronted adverbial?", ["In the evenings,", "people gathered", "the local lord"], 0], ["Which is Standard English?", ["Everyone in the family worked.", "Everyone in the family were working hard and done it.", "Everyone in the family done work."], 0]] },
  { id: "as13-3", title: "Lost in the Fog", type: "Story", text: ["The fog rolled in so quickly that, within minutes, Ravi could no longer see the path ahead. A moment ago, the hills had been bright and green. Now everything was a thick, grey blanket.", "\"Stay where you are,\" said Mrs Hart, the group leader, calmly. \"We'll wait for it to lift.\"", "But Ravi had already wandered a little too far. When he turned round, the others had vanished. He called out, but the fog swallowed his voice.", "Ravi's heart thumped. Then he remembered his training: stay still, stay calm and make a noise. He took the whistle from his rucksack and blew three short blasts.", "Almost at once, he heard three blasts in reply. Mrs Hart's shape appeared out of the mist, and she gave him a relieved hug. \"Well done,\" she said. \"You did exactly the right thing.\""],
    questions: [["How quickly did the fog arrive?", ["within minutes", "over several hours", "overnight"], 0, "retrieval"], ["What did Mrs Hart tell everyone to do?", ["stay where they were", "run back down", "shout loudly"], 0, "retrieval"], ["What does \"the fog swallowed his voice\" mean?", ["the fog made his voice hard to hear", "he lost his voice", "he ate the fog"], 0, "language"], ["What did Ravi remember?", ["his training", "his mum's advice", "a story"], 0, "retrieval"], ["Why did he blow three short blasts?", ["to signal that he needed help", "to scare animals", "to start a game"], 0, "inference"], ["How did Mrs Hart feel when she found Ravi?", ["relieved", "angry", "bored"], 0, "inference"]],
    grammar: [["Which is an expanded noun phrase?", ["a thick, grey blanket", "fog", "he turned"], 0], ["Which is a fronted adverbial with a comma?", ["Almost at once, he heard three blasts.", "He heard three blasts almost at once.", "He heard three blasts."], 0]] },
  { id: "as13-4", title: "Electricity Safety", type: "Information", text: ["Electricity powers our lights, computers, fridges and televisions. It makes our lives much easier, but it can also be very dangerous if it is not used safely.", "Electricity always tries to find a path to the ground. If your body becomes that path, you can get an electric shock, which can cause serious injury.", "To stay safe, never poke anything into a plug socket, and never touch switches or plugs with wet hands, because water lets electricity flow more easily.", "Outdoors, keep well away from electricity pylons and substations, and never fly a kite near overhead power lines.", "If you see someone who has had an electric shock, do not touch them. Instead, switch off the power if you can, and call an adult or the emergency services straight away."],
    questions: [["Give one thing electricity powers.", ["fridges", "bicycles", "candles"], 0, "retrieval"], ["When can a person get an electric shock?", ["when their body becomes a path for electricity to the ground", "when they eat", "when they switch off a light"], 0, "retrieval"], ["Why should you never touch a plug with wet hands?", ["Water lets electricity flow more easily.", "The plug will rust.", "It wastes electricity."], 0, "retrieval"], ["Where should you never fly a kite?", ["near overhead power lines", "in a park", "on a beach"], 0, "retrieval"], ["Why shouldn't you touch someone who has had an electric shock?", ["You might get a shock too.", "They will be cross.", "It is rude."], 0, "inference"], ["What is the purpose of this text?", ["to explain how to stay safe with electricity", "to tell a story", "to sell electricity"], 0, "structure"]],
    grammar: [["Which is a fronted adverbial?", ["Outdoors,", "electricity", "pylons"], 0], ["Which is Standard English?", ["We were careful near the pylons.", "We was careful near the pylons.", "We be careful near the pylons."], 0]] },
  { id: "as13-5", title: "The Night Market", type: "Description", text: ["As soon as the sun set, the empty car park was transformed into a glittering night market. Strings of coloured lanterns swung between the stalls, and the air was filled with the sizzle of frying food and the chatter of hundreds of voices.", "At one stall, a man with a long white apron tossed noodles high into the air and caught them in a sizzling pan. At another, a woman with silver bangles sold spices piled in neat, colourful cones: saffron yellow, chilli red and cinnamon brown.", "Further along, children crowded around a juggler who kept five flaming torches spinning above his head. Every time he caught one, they gasped and clapped.", "By midnight, the lanterns had been switched off, the stalls folded away and the car park was empty and silent once more, as if the market had been nothing but a dream."],
    questions: [["Where was the night market held?", ["in an empty car park", "in a field", "on a beach"], 0, "retrieval"], ["What hung between the stalls?", ["strings of coloured lanterns", "flags", "washing lines"], 0, "retrieval"], ["What did the juggler use?", ["five flaming torches", "balls", "knives"], 0, "retrieval"], ["What does \"transformed\" mean?", ["completely changed", "cleaned", "closed"], 0, "vocabulary"], ["What is the effect of \"as if the market had been nothing but a dream\"?", ["It shows how quickly and completely the market disappeared.", "It shows the writer was asleep.", "It shows the market was boring."], 0, "language"], ["How is the text organised?", ["from sunset to midnight, moving around the market", "as a list of rules", "as a letter"], 0, "structure"]],
    grammar: [["Which is an expanded noun phrase with a preposition?", ["a man with a long white apron", "a man", "he tossed noodles"], 0], ["Which is a fronted adverbial?", ["By midnight,", "the lanterns", "were switched off"], 0]] },
  { id: "as13-6", title: "My Grandad's Hands", type: "Poem", text: ["My grandad's hands are rough and brown,", "Like the bark of an old oak tree;", "They've mended boats in a fishing town,", "And pulled great nets from the sea.", "They've built a shed and dug a well,", "They've held each baby new;", "And when I've fallen, and when I fell,", "They've lifted me up too.", "Now they're slower, and they shake,", "But when they hold my own,", "I feel the strength those old hands make,", "And I know I'm not alone."],
    questions: [["What are Grandad's hands compared to?", ["the bark of an old oak tree", "a fishing net", "a boat"], 0, "language"], ["Name one thing Grandad's hands have done.", ["mended boats", "painted pictures", "played the piano"], 0, "retrieval"], ["What does the poet suggest about Grandad's life?", ["He has worked hard and cared for his family.", "He has always been rich.", "He has never worked."], 0, "inference"], ["How have Grandad's hands changed?", ["They are slower and they shake.", "They are bigger.", "They are softer."], 0, "retrieval"], ["How does the poet feel when Grandad holds their hand?", ["safe and not alone", "embarrassed", "frightened"], 0, "inference"], ["What is the poem mostly about?", ["the poet's love and respect for Grandad", "how to mend a boat", "a fishing trip"], 0, "summarising"]],
    grammar: [["Which is Standard English?", ["They have mended boats.", "They has mended boats.", "They done mended boats."], 0], ["Which phrase is an expanded noun phrase with a preposition?", ["the bark of an old oak tree", "hands", "they shake"], 0]] }
];
ASSESS[14] = [
  { id: "as14-1", title: "The Message in the Bottle", type: "Story", text: ["While she was walking her dog along the shore, Mei spotted something glinting among the seaweed. It was a green glass bottle, sealed with a cork. Inside was a rolled-up piece of paper.", "With shaking fingers, she pulled out the cork. The letter was written in a careful, old-fashioned hand: My name is Thomas. I am nine years old and I live on the island of Skye. If you find this, please write back.", "At the bottom was an address and a date: 12th June 1974.", "Mei showed her parents. \"He'd be over sixty now,\" said her dad. \"Shall we see if he still lives there?\"", "Three weeks later, a reply arrived. Thomas had become a grandfather, and he still lived in the same house. He wrote that he had waited fifty years for that answer, and it had been worth every day."],
    questions: [["Where did Mei find the bottle?", ["among the seaweed on the shore", "in the sea", "in her garden"], 0, "retrieval"], ["How old was Thomas when he wrote the letter?", ["nine", "sixty", "twelve"], 0, "retrieval"], ["Why was the handwriting \"old-fashioned\"?", ["It was written a long time ago.", "It was written by an adult.", "It was messy."], 0, "inference"], ["What did Mei's dad suggest?", ["trying to find out if Thomas still lived there", "throwing the bottle back", "keeping it secret"], 0, "retrieval"], ["How long had the bottle been travelling?", ["about fifty years", "three weeks", "one year"], 0, "inference"], ["How did Thomas feel about getting a reply?", ["it was worth the long wait", "annoyed", "confused"], 0, "inference"]],
    grammar: [["In \"Mei's dad\", what does the apostrophe show?", ["the dad belongs to Mei", "a letter is missing", "there is more than one Mei"], 0], ["In \"He'd be over sixty\", who does \"He\" refer to?", ["Thomas", "Mei's dad", "the dog"], 0]] },
  { id: "as14-2", title: "Rivers", type: "Information", text: ["A river begins its journey high in the hills or mountains, at a place called its source. Often, the source is a spring of water bubbling up from underground, or melting snow.", "In its upper course, the river is narrow and fast. It tumbles over rocks and carves out steep valleys. Waterfalls are often found here.", "As it flows downhill, other streams, called tributaries, join it. The river becomes wider and deeper and starts to slow down. It bends from side to side in loops called meanders.", "Finally, the river reaches the sea at its mouth. Here, it is at its widest and slowest. It drops the sand and mud it has carried all the way from the hills.", "Rivers' banks have always been popular places to live, because they provide water, food and transport."],
    questions: [["What is the source of a river?", ["the place where it begins", "the place where it ends", "a type of fish"], 0, "vocabulary"], ["What is the river like in its upper course?", ["narrow and fast", "wide and slow", "still and deep"], 0, "retrieval"], ["What are tributaries?", ["streams that join the river", "loops in the river", "waterfalls"], 0, "vocabulary"], ["What happens at the river's mouth?", ["It reaches the sea and drops sand and mud.", "It begins.", "It becomes a waterfall."], 0, "retrieval"], ["Why have people always lived near rivers?", ["Rivers provide water, food and transport.", "Rivers are quiet.", "Rivers keep people warm."], 0, "retrieval"], ["How is the text organised?", ["It follows a river from source to mouth.", "It compares two rivers.", "It tells the story of a fish."], 0, "structure"]],
    grammar: [["Which phrase shows plural possession correctly?", ["rivers' banks", "river's banks's", "rivers banks"], 0], ["In \"It tumbles over rocks\", what does \"It\" refer to?", ["the river", "the source", "the valley"], 0]] },
  { id: "as14-3", title: "The Chess Champion", type: "Story", text: ["Everyone at Hill Road School knew that Sam was the best chess player in the club. He had won the school trophy two years in a row.", "So when a quiet new girl called Aisha joined the club, nobody expected much. She sat in the corner, watching, and said almost nothing.", "At the end-of-term tournament, Aisha won every game in the first round. Then she won the second. Soon, only two players were left: Sam and Aisha.", "The game lasted for over an hour. The other children's chatter faded to silence as they gathered round. Finally, Aisha moved her knight. Sam stared at the board, then smiled and held out his hand. \"Checkmate,\" he said. \"Well played.\"", "Later, Aisha admitted that she had been practising with her grandmother every evening since she was five. \"She taught me that the quietest players are often the ones thinking hardest,\" she said."],
    questions: [["How many years had Sam won the trophy?", ["two", "one", "five"], 0, "retrieval"], ["Why did nobody expect much from Aisha?", ["She was new and very quiet.", "She was too young.", "She had never played before."], 0, "inference"], ["What does \"chatter faded to silence\" tell us?", ["Everyone became quiet because the game was so tense.", "The children went home.", "The children were bored."], 0, "language"], ["How did Sam react to losing?", ["He smiled and shook her hand.", "He was angry.", "He cried."], 0, "retrieval"], ["What does this show about Sam?", ["He is a good sport.", "He is a bad loser.", "He did not care."], 0, "inference"], ["What lesson does the story teach?", ["Don't judge people by how quiet they are.", "Chess is boring.", "Always play the knight first."], 0, "summarising"]],
    grammar: [["Which shows plural possession?", ["the other children's chatter", "the child's chatter", "the childrens chatter"], 0], ["In \"She taught me\", who does \"She\" refer to?", ["Aisha's grandmother", "Aisha", "a teacher"], 0]] },
  { id: "as14-4", title: "Recycling Plastic", type: "Explanation", text: ["Every year, millions of tonnes of plastic are thrown away. Plastic is useful because it is light and strong, but these same qualities mean that it takes hundreds of years to break down.", "When plastic bottles are recycled, they go through several stages. First, they are collected and taken to a recycling centre. There, machines sort them by type and colour.", "Next, the bottles are washed and chopped into tiny flakes. The flakes are melted and shaped into small pellets.", "Finally, factories use the pellets to make new products, such as fleece jackets, garden furniture and even new bottles.", "However, not all plastic can be recycled. That is why it is even better to reduce the amount of plastic we use in the first place, for example by using refillable bottles."],
    questions: [["Why does plastic take so long to break down?", ["because it is light and strong", "because it is coloured", "because it is wet"], 0, "retrieval"], ["What happens first in recycling?", ["The bottles are collected.", "The bottles are melted.", "Jackets are made."], 0, "sequencing"], ["What are the flakes turned into?", ["small pellets", "bottles straight away", "paper"], 0, "retrieval"], ["Name a product that can be made from recycled plastic.", ["fleece jackets", "glass windows", "wooden tables"], 0, "retrieval"], ["Why is reducing plastic better than recycling?", ["Not all plastic can be recycled.", "Recycling is fun.", "Plastic is free."], 0, "inference"], ["Which words show the order of the stages?", ["First, Next, Finally", "However, That is why", "millions, hundreds"], 0, "structure"]],
    grammar: [["What is the plural of \"factory\"?", ["factories", "factorys", "factory's"], 0], ["In \"they go through several stages\", what does \"they\" refer to?", ["plastic bottles", "machines", "factories"], 0]] },
  { id: "as14-5", title: "The Wishing Well", type: "Story", text: ["In the middle of the village square stood an old stone well. People said that if you dropped a coin into it, your wish would come true.", "Every day, Leo watched the visitors throw in their coins. A woman wished for a new car. A boy wished for the latest video game. A man wished to win the lottery.", "One evening, Leo noticed an elderly woman sitting alone by the well. She had no coin to throw, so she simply whispered, \"I wish I had someone to talk to.\"", "Leo didn't have a coin either, but he sat down beside her. \"Hello,\" he said. \"Would you like to hear about my day?\"", "The woman's face lit up. They talked until the stars came out. From then on, Leo visited her every week.", "Leo never found out whether the well was really magic. But he knew that some wishes don't need a coin at all."],
    questions: [["What did people believe about the well?", ["A coin would make their wish come true.", "It was dangerous.", "It was full of treasure."], 0, "retrieval"], ["What did most visitors wish for?", ["things they wanted to own or win", "help for others", "rain"], 0, "summarising"], ["Why didn't the elderly woman throw a coin?", ["She had no coin.", "She did not believe in wishes.", "The well was closed."], 0, "retrieval"], ["What was her wish?", ["someone to talk to", "a new car", "money"], 0, "retrieval"], ["How did Leo make her wish come true?", ["He sat and talked with her.", "He gave her a coin.", "He took her home."], 0, "inference"], ["What does the last sentence mean?", ["Kindness can make some wishes come true.", "Wishes are not real.", "Coins are important."], 0, "inference"]],
    grammar: [["Which phrase shows singular possession?", ["the woman's face", "the womens face", "the woman face"], 0], ["In \"He knew\", who does \"He\" refer to?", ["Leo", "the man", "the boy"], 0]] },
  { id: "as14-6", title: "Autumn Leaves", type: "Poem", text: ["The trees have put their summer coats", "In shades of red and gold,", "And one by one they let them drop", "As days grow short and cold.", "The leaves go spinning, dancing, down,", "They crunch beneath our feet,", "They gather in the gutters", "And they blow along the street.", "And though the branches now look bare,", "Don't think the trees are dead:", "They're sleeping, dreaming of the spring,", "Tucked up in winter's bed."],
    questions: [["What colours are the leaves?", ["red and gold", "green and blue", "black and white"], 0, "retrieval"], ["Why do the trees drop their leaves?", ["The days are growing short and cold.", "The wind is too strong.", "People pick them."], 0, "retrieval"], ["What are the leaves compared to in the first verse?", ["summer coats", "hats", "blankets"], 0, "language"], ["Which words show the sound of the leaves?", ["crunch beneath our feet", "spinning, dancing", "short and cold"], 0, "language"], ["What does the poet say the trees are doing in winter?", ["sleeping and dreaming of spring", "dying", "growing"], 0, "retrieval"], ["What is the message of the last verse?", ["The trees will come back to life in spring.", "Winter lasts for ever.", "The trees are dead."], 0, "inference"]],
    grammar: [["In \"they let them drop\", what does \"them\" refer to?", ["the leaves (their coats)", "the trees", "the days"], 0], ["Which phrase shows possession?", ["winter's bed", "the trees", "red and gold"], 0]] }
];

